M_METHO.subtitle = "Dissertation, cas pratique, commentaire d'arrêt et commentaire de texte, avec ateliers d'exercices";
(function () { const L = M_METHO.lessons, get = id => L.find(l => l.id === id), N = {"intro":{"id":"introgen","title":"La méthodologie juridique : les quatre exercices","body":[{"p":"La **méthodologie juridique** désigne l'ensemble des techniques qui permettent de **rechercher, comprendre, interpréter et appliquer** les règles de droit, comme dans le cas pratique et le commentaire d'arrêt. Elle permet aussi de présenter une **démonstration juridique** claire, rigoureuse et structurée, comme dans la dissertation et le commentaire de texte."},{"p":"Elle suppose de maîtriser le **lexique juridique** : chaque science a son vocabulaire et ses règles propres. Les méthodes varient d'un auteur à l'autre ; le cours propose une orientation de base, sous forme d'esquisses, pour les quatre exercices pratiqués en faculté de droit."},{"table":{"h":["Exercice","Ce que l'on attend","Démarche"],"r":[["**La dissertation juridique**","Une démonstration ordonnée sur un sujet théorique","Analyse du sujet, problématique, plan en deux parties"],["**Le cas pratique**","La résolution des problèmes de droit posés par des faits","Faits, qualification, problème, règle, application, solution"],["**Le commentaire d'arrêt**","L'explication et l'appréciation d'une décision de justice","Fiche d'arrêt, puis commentaire en deux parties"],["**Le commentaire de texte**","L'explication et la discussion d'un texte doctrinal ou juridique","Analyse du texte, problématique, plan en deux parties"]]}},{"box":"La réussite en droit ne dépend pas seulement de la mémorisation des cours. Elle suppose une méthode pour **comprendre** une situation juridique, **identifier** les règles applicables, **construire** un raisonnement et **présenter** une réponse claire et argumentée.","title":"Pourquoi une méthode","kind":"cle"}]},"dissBody":[{"h":"Définition"},{"p":"La **dissertation juridique** est un exercice de **réflexion et de démonstration**. Le mot vient du latin *disserere* : exposer des raisonnements, des idées liés les uns aux autres. Elle se distingue de la dissertation de français ou de philosophie par sa **consistance**, un discours ordonné et cohérent sur un problème envisagé dans sa dimension juridique, et par sa **forme**, un plan binaire (en deux parties)."},{"table":{"h":["Exigence","Ce qu'elle signifie"],"r":[["**L'exhaustivité**","Tous les aspects importants du sujet doivent être abordés."],["**La rigueur**","Éviter deux écueils : le **hors-sujet** et la **non-correspondance** des développements au problème juridique, à la réponse donnée et aux intitulés du plan."]]}},{"p":"La dissertation vérifie la capacité de l'étudiant à **comprendre** un sujet, **mobiliser** ses connaissances, **problématiser**, **organiser** ses idées et **construire** une démonstration."},{"h":"Au brouillon"},{"ol":["**Analyser le sujet.** Lire et relire l'énoncé, puis **définir chaque terme**. Pour « La loi est-elle une source exclusive du droit ? », on définit la *loi*, la *source*, le *droit* et *exclusive*. Ensuite, **délimiter** le sujet : en faire le tour complet, puis ne retenir que les aspects pertinents.","**Dégager la problématique.** Elle transforme le sujet en une véritable **question juridique**, de préférence sous forme interrogative. Elle doit appeler un débat, tout en permettant une réponse concise.","**Faire l'inventaire des connaissances.** Rassembler tout ce que l'on sait sur le sujet (cours, lectures, recherches en bibliothèque, documents fournis), puis trier pour ne garder que ce qui sert le problème posé.","**Formuler le plan.** Il peut être trouvé avant ou après la problématique : c'est un travail de brouillon, au choix de l'étudiant. Mais le plan doit toujours **répondre au problème posé**. Le plan classique comporte **deux parties**, divisées chacune en **deux sous-parties**."]},{"box":"Quand le sujet est accompagné de documents, chacun doit nourrir un argument précis du plan : on le cite et on l'exploite, on ne le recopie pas.","title":"Avec une documentation","kind":"marge"},{"h":"Sur la copie : l'introduction"},{"p":"La rédaction s'inspire du travail de brouillon. Elle comporte trois parties : l'**introduction**, le **développement** et la **conclusion**. L'introduction comprend six éléments :"},{"table":{"h":["Élément","Contenu"],"r":[["**1. L'accroche**","Une entrée en matière en lien direct avec le sujet : une **citation** entre guillemets (expression ou pensée d'un auteur, adage juridique connu) ou une **disposition d'un texte juridique**. Les références littéraires ou historiques sont admises si elles ont un lien avec le sujet. À proscrire : « De tout temps… », « Depuis que le monde est monde… »."],["**2. Les définitions**","Une définition d'ensemble et contextuelle des mots clés, telle qu'établie au brouillon."],["**3. La délimitation**","La circonscription du sujet. Elle peut varier d'un étudiant à l'autre, mais certains sujets imposent une feuille de route : ne pas la suivre, c'est être hors sujet."],["**4. L'intérêt du sujet**","**Intérêt théorique** : l'actualité du droit sur le sujet, un débat doctrinal, une conférence ou un colloque. **Intérêt pratique** : un fait marquant, un cas connu d'application réussie ou ratée d'une constitution ou d'une loi, une jurisprudence."],["**5. La problématique**","La question qui exprime le débat, posée sous forme interrogative."],["**6. L'annonce du plan**","Elle justifie le plan : elle annonce les deux parties (I et II) comme la réponse au problème posé, de façon élégante."]]}},{"h":"Le développement"},{"p":"Chaque partie comporte une **idée principale**, des **explications**, des **arguments juridiques**, des **illustrations** et une **transition**. Un court chapeau sous chaque partie annonce ses deux sous-parties."},{"box":"Un paragraphe qui se contente de décrire ou de réciter n'apporte rien : chaque paragraphe doit faire avancer la démonstration.","title":"Pas de paragraphe descriptif","kind":"piege"},{"h":"La conclusion"},{"p":"La conclusion **répond à la problématique**. Elle est **courte** : ce n'est pas le lieu d'un bilan ni d'une reprise des grands axes, mais plutôt d'une **ouverture** du sujet traité."},{"box":"Contrairement à l'introduction et au développement, qui sont obligatoires, la conclusion est **facultative** dans une dissertation juridique.","title":"Une conclusion facultative","kind":"cle"}],"dissexo":{"id":"dissexo","title":"Au brouillon : « La loi est-elle une source exclusive du droit ? »","body":[{"p":"Application de la phase de brouillon à un sujet du cours : définitions, problématique, inventaire des connaissances et plan."},{"p":"**Sujet** : « La loi est-elle une source exclusive du droit ? »"},{"h":"Les définitions"},{"table":{"h":["Terme","Définition retenue"],"r":[["**Loi**","Au sens formel, l'acte voté par le Parlement ; au sens matériel, toute règle écrite, générale et impersonnelle."],["**Source**","L'origine d'une règle de droit, ce qui lui donne naissance et force obligatoire."],["**Droit**","Le droit objectif : l'ensemble des règles qui régissent la vie en société, sanctionnées par l'autorité publique."],["**Exclusive**","Qui exclut toute autre : unique, seule."]]}},{"p":"**Problématique** : la loi est-elle la seule origine des règles de droit, ou partage-t-elle ce rôle avec d'autres sources ?"},{"h":"L'inventaire des connaissances"},{"ul":["La place de la loi dans un système de droit écrit, d'inspiration romano-germanique, comme celui de la Côte d'Ivoire.","Les normes écrites supérieures à la loi : la Constitution et les traités régulièrement ratifiés, dont le traité OHADA et ses Actes uniformes.","Les règlements : règlements autonomes (article 103 de la Constitution) et décrets d'application.","La coutume : *secundum legem* (à laquelle la loi renvoie), *praeter legem* (qui comble un vide) et *contra legem* (contraire à la loi).","La jurisprudence : le juge doit statuer même en cas de silence de la loi (article 4 du Code civil), sans pouvoir rendre d'arrêt de règlement (article 5).","La doctrine, autorité qui inspire le législateur et le juge."]},{"h":"Le plan proposé"},{"ul":["**I. La loi, une source prépondérante du droit** — A. Une source privilégiée par le système de droit écrit ; B. Une source à laquelle d'autres règles sont subordonnées (décrets d'application, coutume *secundum legem*).","**II. La loi, une source concurrencée** — A. Par d'autres normes écrites : Constitution, traités, règlements autonomes ; B. Par des sources non écrites : la coutume et la jurisprudence."]}]},"casexo":{"id":"casexo","title":"Exercice corrigé : Émile, Émilie et l’enfant de Showman","body":[{"box":"Le 1er janvier 2026, les jumeaux Émile et Émilie fêtent le nouvel an chez leur ami Showman, dans sa villa d'Assinie, en bord de mer. Émile sort prendre l'air et ne donne plus jamais signe de vie. Émilie part faire un tour en yacht avec Showman ; quelques heures plus tard, la police maritime découvre le bateau en feu au milieu de la mer et le corps sans vie de Showman. Émilie reste introuvable. Après des mois d'attente, les parents des jumeaux veulent savoir si leurs enfants sont morts et s'ils peuvent organiser leurs funérailles. Deux semaines après le drame, Pretty Girl, fiancée de Showman, découvre qu'elle est enceinte de deux mois. La famille de Showman estime que l'enfant à naître n'a aucun droit sur sa succession, son père étant décédé avant sa naissance.","title":"L’énoncé","kind":"marge"},{"quote":"**Résumé des faits.** Le 1er janvier 2026, au cours d'une fête à Assinie, Émile sort se promener et ne donne plus de nouvelles. Sa sœur jumelle Émilie embarque sur le yacht de Showman ; le bateau est retrouvé en feu en pleine mer, avec le corps de Showman, mais Émilie reste introuvable. Leurs parents veulent savoir s'ils peuvent les tenir pour morts et organiser leurs funérailles. Par ailleurs, la fiancée de Showman est enceinte de lui depuis environ six semaines au jour du décès ; la famille du défunt refuse tout droit successoral à l'enfant à naître."},{"quote":"**Qualification juridique.** Les faits ainsi présentés se rapportent à l'**incertitude sur l'existence de la personne physique** et à l'**acquisition de la personnalité juridique par l'enfant simplement conçu**."},{"quote":"**Problèmes de droit.** Ils posent les problèmes suivants : quelle est la situation juridique d'Émile, et ses parents peuvent-ils le tenir pour mort ? Quelle est la situation juridique d'Émilie, et à quelles conditions ses parents pourront-ils la tenir pour morte ? L'enfant simplement conçu au jour du décès de son père peut-il recueillir la succession de celui-ci ? La situation de chaque jumeau et la question des funérailles relèvent de la même règle : elles sont donc réunies en un seul problème."},{"quote":"**Plan.** Nous résoudrons ces problèmes dans l'ordre ainsi établi."},{"quote":"**I. La situation juridique d'Émile.** Émile est sorti prendre l'air au cours de la fête et n'a plus jamais donné de nouvelles. Est-il absent ou disparu, et ses parents peuvent-ils le tenir pour mort ? **En droit**, selon l'article 1er de la loi n° 2022-885 relative à l'absence et à la disparition, l'absent est la personne qui a cessé de paraître au lieu de son domicile ou de sa résidence sans que l'on ait de ses nouvelles, de sorte que son existence est devenue incertaine. Selon l'article 13, le disparu est celui qui a cessé de paraître à la suite de circonstances de nature à mettre sa vie en danger, sans que son corps ait pu être retrouvé. L'absent est présumé vivant : un an après les dernières nouvelles, le tribunal peut être saisi d'une demande de présomption d'absence ; après enquête, il rend un jugement déclaratif d'absence, et le décès ne peut être déclaré que sept ans après ce jugement ou dix ans après les dernières nouvelles. **En l'espèce**, aucun élément de l'énoncé ne montre qu'Émile a été exposé à un danger : il est simplement sorti se promener, et l'on ne saurait inventer une noyade que les faits ne mentionnent pas. **Par conséquent**, Émile est absent. Ses parents ne peuvent pas le tenir pour mort ni organiser ses funérailles : ils pourront, à partir du 1er janvier 2027, demander au tribunal de constater la présomption d'absence."},{"quote":"**II. La situation juridique d'Émilie.** Émilie a embarqué sur le yacht retrouvé en feu en pleine mer ; le corps de Showman a été découvert, pas le sien. Est-elle disparue, et à quelles conditions ses parents pourront-ils la tenir pour morte ? **En droit**, le disparu est la personne qui a cessé de paraître à la suite de circonstances de nature à mettre sa vie en danger, sans que son corps ait pu être retrouvé (article 13 de la loi n° 2022-885). Son décès étant probable, le tribunal peut rendre directement un jugement déclaratif de décès, après enquête et au plus tôt un an après la disparition ; ce jugement tient lieu d'acte de décès. **En l'espèce**, Émilie se trouvait sur un bateau en feu en pleine mer, circonstance de nature à mettre sa vie en danger, et son corps n'a pas été retrouvé. **Par conséquent**, Émilie est disparue. Ses parents pourront, à partir du 1er janvier 2027, demander un jugement déclaratif de décès ; c'est seulement alors qu'elle sera juridiquement tenue pour morte et que ses funérailles et sa succession pourront être organisées."},{"quote":"**III. Les droits de l'enfant à naître sur la succession de Showman.** Pretty Girl, fiancée de Showman, était enceinte de lui depuis environ six semaines au jour de son décès. L'enfant simplement conçu au jour du décès de son père peut-il hériter de lui ? **En droit**, selon l'adage *infans conceptus pro nato habetur quoties de commodis ejus agitur*, l'enfant conçu est réputé né chaque fois qu'il y va de son intérêt. La loi n° 2019-573 du 26 juin 2019 relative aux successions admet ainsi à la succession l'enfant déjà conçu au jour de l'ouverture de celle-ci, à la seule condition qu'il naisse vivant. Encore faut-il que sa filiation à l'égard du défunt soit établie. **En l'espèce**, l'enfant était conçu au jour du décès de Showman, qui ouvre sa succession. Ses parents n'étant pas mariés et Showman n'ayant pas reconnu l'enfant, sa filiation paternelle devra être établie en justice, par une action en recherche de paternité. **Par conséquent**, contrairement à ce que soutient la famille de Showman, l'enfant pourra, s'il naît vivant et une fois sa filiation établie, venir à la succession de son père comme tout autre enfant du défunt. Pretty Girl, simple fiancée, n'a en revanche aucun droit personnel sur cette succession."}]},"ficheexo":{"id":"ficheexo","title":"Exercice corrigé : la fiche de l’arrêt du 16 décembre 1975","body":[{"box":"Cass. civ., 16 décembre 1975, observations R. Lindon. S…, né en 1909, de sexe masculin, porte les prénoms de Georges, Marie, André. Après des interventions qu'il dit avoir subies pendant sa détention en 1939-1945, sa morphologie s'est féminisée. Il demande à supprimer le prénom de Georges et à réunir ceux de Marie et André. La cour d'appel de Nancy refuse, au motif que le prénom de Georges n'est pas ridicule ; la Cour de cassation casse cet arrêt.","title":"La décision en bref","kind":"marge"},{"quote":"**Références.** Il s'agit d'un arrêt de cassation rendu par la chambre civile de la Cour de cassation française le 16 décembre 1975, dans un litige relatif à la demande de modification de prénoms formée par S…"},{"quote":"**Faits.** S…, né le 9 juin 1909, est déclaré de sexe masculin sous les prénoms de Georges, Marie, André. Marié en 1940, il divorce en 1948. Pendant la guerre de 1939-1945, il est incarcéré à Épinal, où des médecins allemands auraient pratiqué sur lui certaines interventions. Peu après, sa morphologie se transforme : ses organes génitaux s'atrophient, sa poitrine se développe et sa voix prend un timbre féminin."},{"quote":"**Procédure.** Sur le fondement de l'article 57, alinéa 3, du Code civil, S… demande en justice la suppression de son prénom de Georges et la réunion de ceux de Marie et André par un trait d'union. Les premiers juges font droit à sa demande. Sur appel, la cour d'appel de Nancy, par un arrêt du 5 avril 1973, réforme ce jugement, au motif que S… ne justifie pas d'un intérêt légitime, le prénom de Georges n'étant nullement ridicule. S… forme un pourvoi en cassation."},{"quote":"**Problème de droit.** Le juge peut-il refuser une modification de prénom pour défaut d'intérêt légitime en se bornant à relever que le prénom, considéré en lui-même, n'est pas ridicule ?"},{"quote":"**Solution.** Au motif qu'en se bornant à relever que le prénom de Georges, considéré en lui-même, n'est pas ridicule, sans s'expliquer sur la situation personnelle de l'intéressé retenue par les premiers juges, la cour d'appel a entaché sa décision d'un défaut de motifs et n'a pas satisfait aux exigences de l'article 102 du décret du 20 juillet 1972, la Cour de cassation casse et annule l'arrêt et renvoie les parties devant la cour d'appel de Reims."},{"box":"L'intérêt légitime au changement de prénom s'apprécie **au regard de la situation concrète du demandeur**, et non du prénom pris isolément. La cassation est prononcée pour **défaut de motifs** : la Cour ne tranche pas elle-même la question de fond, ce qui limite la portée de l'arrêt. La question de la transformation de l'apparence sexuelle sera tranchée bien plus tard, lorsque l'Assemblée plénière de la Cour de cassation admettra, le 11 décembre 1992, la modification de la mention du sexe à l'état civil.","title":"Portée","kind":"marge"},{"p":"**Plan de commentaire proposé**"},{"ul":["I. L'exigence d'un intérêt légitime au changement de prénom (A. Un changement subordonné à un intérêt légitime ; B. Un intérêt apprécié au regard de la situation du demandeur)","II. La censure d'une motivation insuffisante (A. Le défaut de motifs, cas d'ouverture à cassation ; B. Une portée limitée, en attendant la reconnaissance du changement de sexe)"]}]},"atel":[{"id":"atelier1","title":"Atelier 1 : les réflexes du juriste","body":[{"p":"Trois réflexes servent dans tous les exercices de méthodologie : **qualifier** les faits, **trier** ce qui compte et **raisonner** dans l'ordre (règle, faits, solution). Fais chaque exercice au brouillon avant d'ouvrir le corrigé."},{"h":"Exercice 1 : qualifier les faits"},{"p":"Donne la **qualification juridique** de chaque situation : nomme-la en termes juridiques."},{"ol":["Awa achète une miche de pain à la boutique du quartier.","Yao prête 500 000 FCFA à son cousin, qui promet de les lui rendre dans six mois.","Fatou, 15 ans, vend son téléphone portable sans l'accord de ses parents.","Un magazine publie la photo d'une chanteuse prise à son insu dans sa maison.","M. Kouassi est parti de son domicile il y a trois ans ; depuis, personne n'a de ses nouvelles.","Un enfant naît vivant deux mois après la mort de son père.","Koné et Adjoua s'unissent devant l'officier de l'état civil de Cocody.","Un chauffeur de gbaka renverse un piéton sur un passage protégé."]},{"corrige":[{"table":{"h":["Situation","Qualification juridique"],"r":[["1. Le pain","Un **contrat de vente** : Awa est l'acheteuse, le boutiquier le vendeur."],["2. Le prêt","Un **prêt d'argent** (prêt de consommation) : Yao est le prêteur, son cousin l'emprunteur, tenu de restituer la même somme."],["3. Le téléphone","Un acte juridique passé par un **mineur non émancipé**, frappé d'une **incapacité d'exercice** : la vente est annulable (articles 1124 et 1125 du Code civil)."],["4. La photo","Une **atteinte au droit à l'image et à la vie privée**, droits de la personnalité."],["5. M. Kouassi","Une situation d'**absence** : il a cessé de paraître sans donner de nouvelles, son existence est incertaine (article 1er de la loi n° 2022-885)."],["6. L'enfant","Un **enfant conçu** au jour du décès : la règle *infans conceptus* lui permet de recueillir les droits nés avant sa naissance, s'il naît vivant."],["7. Le mariage","Un **mariage**, acte juridique solennel célébré par l'officier de l'état civil."],["8. Le piéton","Un **accident de la circulation** : fait juridique qui engage la responsabilité civile du conducteur ; il peut aussi constituer une infraction de **blessures involontaires**."]]}}]},{"h":"Exercice 2 : trier les faits"},{"p":"Lis l'énoncé, puis sépare les **faits utiles** des **faits de décor**."},{"quote":"Par une belle soirée d'harmattan, Ibrahim, 17 ans, élève brillant en classe de terminale et grand amateur de football, se rend au marché d'Adjamé avec son meilleur ami. Séduit par une moto rouge flambant neuve, il l'achète 900 000 FCFA à crédit, sans en parler à ses parents. Il verse une avance de 100 000 FCFA, économisée sur son argent de poche. Furieux, son père veut faire annuler la vente."},{"corrige":[{"table":{"h":["Faits utiles","Pourquoi"],"r":[["Ibrahim a **17 ans**","Il est mineur : c'est la clé de la qualification (incapacité d'exercice)."],["Il **achète** une moto **900 000 FCFA à crédit**","C'est l'acte juridique en cause ; son importance montre qu'il ne s'agit pas d'un acte de la vie courante."],["**Sans l'accord** de ses parents","Ses représentants légaux n'ont pas consenti à l'acte."],["Il verse une **avance de 100 000 FCFA**","Elle commande les restitutions si la vente est annulée."],["Son **père veut annuler** la vente","C'est la question posée par la personne qui consulte."]]}},{"p":"**Faits de décor** : la soirée d'harmattan, la classe de terminale, le football, le meilleur ami, la couleur de la moto. Ils rendent l'histoire vivante mais ne changent rien à la solution."}]},{"h":"Exercice 3 : remettre le raisonnement dans l'ordre"},{"p":"Les phrases suivantes forment un raisonnement complet, mais elles sont mélangées. Remets-les dans l'ordre : **problème, règle, application, solution**."},{"ol":["En l'espèce, Ibrahim a 17 ans et a acheté seul, sans l'accord de ses parents, une moto de 900 000 FCFA à crédit.","Par conséquent, la vente est annulable à la demande d'Ibrahim, représenté par son père ; le vendeur ne peut pas, lui, invoquer l'incapacité.","Un mineur peut-il obtenir l'annulation d'une vente qu'il a conclue seul ?","En droit, les mineurs sont incapables de contracter (article 1124 du Code civil) ; seul l'incapable peut attaquer son engagement pour cause d'incapacité, les personnes capables qui ont contracté avec lui ne le peuvent pas (article 1125)."]},{"corrige":[{"p":"L'ordre est **3, 4, 1, 2** : le **problème** (3), la **règle** introduite par « En droit » (4), l'**application** introduite par « En l'espèce » (1), puis la **solution** introduite par « Par conséquent » (2)."},{"box":"Les mots d'articulation sont des panneaux : « En droit » annonce la règle, « En l'espèce » les faits, « Par conséquent » la solution. Si une phrase ne commence par aucun d'eux, demande-toi quelle fonction elle remplit.","title":"Le moyen de s'en souvenir","kind":"cle"}]}]},{"id":"atelier2","title":"Atelier 2 : la dissertation pas à pas","body":[{"p":"La dissertation fait peur parce qu'on veut tout écrire d'un coup. Ici, on la découpe en étapes courtes : définir, problématiser, construire le plan, puis rédiger l'introduction."},{"h":"Exercice 4 : choisir une bonne accroche"},{"p":"Pour le sujet « La loi est-elle une source exclusive du droit ? », classe ces accroches de la meilleure à la moins bonne et justifie."},{"ol":["« De tout temps, les hommes ont eu besoin de règles. »","« La loi est l'expression de la volonté générale » (article 6 de la Déclaration des droits de l'homme et du citoyen de 1789).","« Le juge ne peut refuser de juger sous prétexte du silence, de l'obscurité ou de l'insuffisance de la loi » (article 4 du Code civil).","« Le football est la chose la plus importante parmi les choses sans importance. »"]},{"corrige":[{"p":"**3, puis 2, puis 1 et 4.** L'accroche 3 est la meilleure : c'est une disposition d'un texte juridique, et elle pose déjà le débat, puisque le juge doit statuer même quand la loi se tait, donc la loi ne suffit pas. L'accroche 2, citation célèbre, est en lien direct avec la loi, mais elle n'annonce pas le débat sur les autres sources. L'accroche 1 est à proscrire (« De tout temps… »). L'accroche 4 n'a aucun lien avec le sujet."}]},{"h":"Exercice 5 : définir, délimiter, problématiser"},{"p":"Sujet : « **La coutume est-elle encore une source du droit en Côte d'Ivoire ?** » Définis les termes clés, délimite le sujet, puis formule la problématique."},{"corrige":[{"table":{"h":["Terme","Définition"],"r":[["**Coutume**","Règle non écrite née d'un usage ancien, constant et général (élément matériel), que le groupe considère comme obligatoire (élément psychologique)."],["**Encore**","Le mot invite à comparer hier et aujourd'hui : la coutume, autrefois dominante, a-t-elle survécu à la codification ?"],["**Source du droit**","Origine d'une règle de droit qui lui donne force obligatoire."],["**En Côte d'Ivoire**","Le sujet est limité au droit ivoirien ; le droit comparé ne vient qu'en illustration."]]}},{"p":"**Délimitation** : le droit positif ivoirien depuis l'indépendance, en particulier les réformes de 1964 en droit de la famille et le droit foncier rural."},{"p":"**Problématique** : la codification a-t-elle fait disparaître la coutume, ou celle-ci conserve-t-elle une place parmi les sources du droit ivoirien ?"}]},{"h":"Exercice 6 : construire le plan"},{"p":"Sur le même sujet, propose un plan en deux parties et deux sous-parties qui réponde à la problématique."},{"corrige":[{"ul":["**I. Une source largement écartée par la loi écrite** — A. La substitution de la loi à la coutume en droit de la famille, depuis les réformes de 1964 ; B. La primauté de la loi écrite dans un système de droit codifié.","**II. Une source qui subsiste** — A. La reconnaissance des droits coutumiers sur la terre (loi n° 98-750 du 23 décembre 1998 relative au domaine foncier rural) ; B. Les usages, notamment commerciaux, auxquels la loi renvoie ou qui comblent ses silences."]},{"box":"Lis les quatre titres à la suite : ils doivent former une réponse à la problématique. Ici : la coutume est largement écartée (I), mais elle subsiste dans des domaines précis (II).","title":"Vérifier son plan","kind":"cle"}]},{"h":"Exercice 7 : rédiger une introduction complète"},{"p":"Rédige l'introduction du sujet « La loi est-elle une source exclusive du droit ? » en suivant les six éléments du cours : accroche, définitions, délimitation, intérêt, problématique, annonce du plan."},{"corrige":[{"quote":"**Accroche.** « Le juge ne peut refuser de juger sous prétexte du silence, de l'obscurité ou de l'insuffisance de la loi. » En imposant au juge de statuer même lorsque la loi se tait, l'article 4 du Code civil reconnaît implicitement que la loi ne peut tout prévoir."},{"quote":"**Définitions.** La **loi**, au sens formel, est l'acte voté par le Parlement ; au sens matériel, elle désigne toute règle écrite, générale et impersonnelle. Une **source du droit** est l'origine d'une règle qui lui donne force obligatoire. Le **droit** s'entend ici du droit objectif, ensemble des règles qui régissent la vie en société. Est **exclusive** la source qui écarte toutes les autres."},{"quote":"**Délimitation.** Le sujet sera envisagé en droit positif ivoirien, système de droit écrit hérité de la tradition romano-germanique, sans négliger l'apport des normes internationales et communautaires."},{"quote":"**Intérêt.** Sur le plan théorique, le sujet interroge la hiérarchie des normes et le rôle créateur du juge. Sur le plan pratique, il commande le travail du juriste : savoir où chercher la règle applicable, dans la loi, mais aussi dans un traité, un Acte uniforme OHADA ou une coutume."},{"quote":"**Problématique.** Dès lors, la loi est-elle la seule origine des règles de droit, ou partage-t-elle ce rôle avec d'autres sources ?"},{"quote":"**Annonce du plan.** Si la loi demeure une source prépondérante du droit **(I)**, elle n'en est pas moins concurrencée par d'autres sources, écrites et non écrites **(II)**."}]}]},{"id":"atelier3","title":"Atelier 3 : le cas pratique en entier","body":[{"p":"On passe à la résolution complète : d'abord un cas à un seul problème, rédigé en bloc, puis un exercice sur l'art de poser et de regrouper les problèmes."},{"h":"Exercice 8 : un seul problème, rédigé en bloc"},{"quote":"Ibrahim, 17 ans, a acheté seul au marché d'Adjamé une moto de 900 000 FCFA à crédit, sans l'accord de ses parents, en versant une avance de 100 000 FCFA. Son père veut faire annuler la vente. Le vendeur répond que la vente est définitive et qu'il gardera l'avance."},{"p":"Résous ce cas pratique."},{"corrige":[{"quote":"**Résumé des faits.** Ibrahim, 17 ans, achète seul et à crédit une moto de 900 000 FCFA, sans l'accord de ses parents, et verse une avance de 100 000 FCFA. Son père souhaite faire annuler la vente ; le vendeur s'y oppose et entend conserver l'avance."},{"quote":"**Qualification juridique.** Ces faits se rapportent à l'**incapacité d'exercice du mineur non émancipé**."},{"quote":"**Problème de droit.** Une vente conclue seul par un mineur non émancipé peut-elle être annulée, et avec quelles conséquences ?"},{"quote":"**En droit**, les mineurs sont incapables de contracter (article 1124 du Code civil). Seul l'incapable peut attaquer son engagement pour cause d'incapacité, la personne capable qui a contracté avec lui ne le pouvant pas (article 1125). Le mineur non émancipé peut en outre obtenir la rescision de toute convention pour simple lésion (article 1305). L'action dure dix ans et ne court, à son égard, qu'à compter de sa majorité (article 1304). En cas d'annulation, les parties se restituent ce qu'elles ont reçu, mais le mineur n'a à rembourser ce qui lui a été payé que dans la mesure où cela a tourné à son profit (article 1312)."},{"quote":"**En l'espèce**, Ibrahim, âgé de 17 ans, est mineur. Il a conclu seul, sans l'accord de ses représentants légaux, l'achat à crédit d'un bien d'une valeur importante, qui n'a rien d'un acte de la vie courante. Son père, qui le représente, peut agir en son nom ; le vendeur, lui, ne peut se prévaloir de l'incapacité pour maintenir ou rompre le contrat à sa guise."},{"quote":"**Par conséquent**, la vente peut être annulée à la demande d'Ibrahim, représenté par son père. L'annulation remet les parties dans l'état antérieur : Ibrahim rend la moto, et le vendeur doit restituer l'avance de 100 000 FCFA. Le vendeur n'est donc pas fondé à conserver cette somme."}]},{"h":"Exercice 9 : poser et regrouper les problèmes"},{"quote":"M. Gnangbo a quitté son domicile de Daloa il y a deux ans sans laisser d'adresse ; depuis, personne n'a de ses nouvelles. Son épouse voudrait savoir si elle peut se remarier, et si elle peut vendre seule leur maison commune. Leur fils de 16 ans, de son côté, a vendu seul la voiture de son père."},{"p":"Sans rédiger, dresse la liste des problèmes de droit, dans l'ordre logique, en regroupant ceux qui relèvent d'une même règle."},{"corrige":[{"ol":["**La situation juridique de M. Gnangbo** : est-il absent ou disparu ? C'est la question préalable, dont dépendent les deux suivantes.","**Les conséquences de l'absence pour son épouse** : peut-elle se remarier et vendre seule la maison commune ? Ces deux difficultés relèvent du même régime, celui des effets de l'absence (présomption puis déclaration d'absence) : on peut les réunir en un seul problème.","**La vente de la voiture par le fils mineur** : un mineur non émancipé peut-il vendre seul un bien, de surcroît un bien qui ne lui appartient pas ? Ce problème relève d'une autre règle, l'incapacité du mineur : il reste distinct."]},{"box":"On classe les problèmes du préalable vers la conséquence, et on regroupe ceux qui se résolvent par la même règle de droit. Ici : trois difficultés au départ, mais seulement trois problèmes dont un réunit deux questions.","title":"Ce qu'il faut retenir","kind":"cle"}]}]},{"id":"atelier4","title":"Atelier 4 : la fiche d'arrêt sans peur","body":[{"p":"Un arrêt de cassation se lit comme une carte : chaque formule indique où l'on se trouve. On apprend d'abord à repérer les parties de l'arrêt, puis à en tirer la fiche, et enfin à corriger une fiche ratée."},{"h":"Exercice 10 : repérer les parties de l'arrêt"},{"p":"Lis cet arrêt d'entraînement et indique où se trouvent : le **visa**, les **faits**, la **procédure** (décision attaquée), les **motifs** de la Cour et le **dispositif**."},{"quote":"**Cour de cassation, chambre civile, 12 mars 2025** *(arrêt d'entraînement rédigé pour l'exercice)*"},{"quote":"Vu l'article 1382 du Code civil ;"},{"quote":"Attendu, selon l'arrêt attaqué, que Mme Aya K…, chanteuse, a été photographiée à son insu alors qu'elle se reposait avec ses enfants dans la cour de sa résidence secondaire de Grand-Bassam ; que le magazine « Star Ivoire » a publié ces photographies en couverture ; que Mme K… a assigné la société éditrice en réparation de son préjudice ;"},{"quote":"Attendu que, pour rejeter cette demande, l'arrêt retient que Mme K…, personnalité publique très connue, ne peut s'opposer à la publication de son image, qui intéresse ses admirateurs ;"},{"quote":"Attendu cependant que toute personne, quelle que soit sa notoriété, a droit au respect de sa vie privée et peut s'opposer à la diffusion, sans son autorisation, de son image saisie dans un lieu privé ; qu'en statuant ainsi, la cour d'appel a violé le texte susvisé ;"},{"quote":"Par ces motifs : casse et annule, en toutes ses dispositions, l'arrêt rendu le 4 juin 2024 par la cour d'appel d'Abidjan ; renvoie la cause et les parties devant la cour d'appel de Bouaké."},{"corrige":[{"table":{"h":["Partie","Où la trouver dans l'arrêt"],"r":[["**Le visa**","« Vu l'article 1382 du Code civil » : le texte sur lequel la Cour fonde sa décision ; sa présence annonce une cassation."],["**Les faits**","Le premier « Attendu » : la photographie prise à son insu dans sa résidence, puis sa publication par le magazine."],["**La procédure**","L'assignation en réparation, puis le deuxième « Attendu » : la cour d'appel rejette la demande, au motif qu'une personnalité publique ne peut s'opposer à la publication."],["**Les motifs**","De « Attendu cependant que » jusqu'à « Par ces motifs » : toute personne, quelle que soit sa notoriété, peut s'opposer à la diffusion de son image saisie dans un lieu privé."],["**Le dispositif**","Après « Par ces motifs » : « casse et annule… renvoie… devant la cour d'appel de Bouaké »."]]}}]},{"h":"Exercice 11 : dresser la fiche"},{"p":"Établis la fiche complète de cet arrêt : nature de la décision, faits, procédure, problème de droit, solution."},{"corrige":[{"quote":"**Références.** Il s'agit d'un arrêt de cassation rendu par la chambre civile de la Cour de cassation le 12 mars 2025, dans un litige opposant Mme Aya K… à la société éditrice du magazine « Star Ivoire »."},{"quote":"**Faits.** Mme K…, chanteuse, est photographiée à son insu alors qu'elle se repose avec ses enfants dans la cour de sa résidence secondaire. Le magazine « Star Ivoire » publie ces photographies en couverture."},{"quote":"**Procédure.** Mme K… assigne la société éditrice en réparation de son préjudice. Par un arrêt du 4 juin 2024, la cour d'appel d'Abidjan rejette sa demande, au motif qu'une personnalité publique très connue ne peut s'opposer à la publication de son image. Mme K… forme un pourvoi en cassation."},{"quote":"**Problème de droit.** Une personne publique peut-elle s'opposer à la diffusion, sans son autorisation, de son image saisie dans un lieu privé ?"},{"quote":"**Solution.** Au motif que toute personne, quelle que soit sa notoriété, a droit au respect de sa vie privée et peut s'opposer à la diffusion, sans son autorisation, de son image saisie dans un lieu privé, la Cour de cassation casse et annule l'arrêt de la cour d'appel d'Abidjan et renvoie les parties devant la cour d'appel de Bouaké."}]},{"h":"Exercice 12 : corriger une fiche ratée"},{"p":"Un étudiant a rendu la fiche ci-dessous. Relève ses erreurs, puis corrige-les."},{"quote":"**Faits.** Attendu que Mme K… a été photographiée ; que le magazine a publié les photos ; qu'elle réclame beaucoup d'argent au magazine, qui a eu tort."},{"quote":"**Procédure.** La cour d'appel a rejeté."},{"quote":"**Problème de droit.** Mme K… peut-elle obtenir de l'argent du magazine « Star Ivoire » ?"},{"quote":"**Solution.** La Cour casse et annule l'arrêt, renvoie devant la cour d'appel de Bouaké, parce que la vie privée doit être respectée."},{"corrige":[{"table":{"h":["Erreur","Correction"],"r":[["Les faits recopient les « **que** » de l'arrêt.","Raconter avec ses propres mots, au présent : « Mme K… est photographiée à son insu… »"],["Les faits contiennent une **prétention** (« elle réclame ») et un **jugement de valeur** (« qui a eu tort »).","Les prétentions vont dans la procédure ; aucun avis personnel dans la fiche."],["La procédure est **incomplète** : ni assignation, ni date, ni motif de la cour d'appel, ni pourvoi.","Préciser qui agit, devant quelle juridiction, pour demander quoi, et le sens de chaque décision."],["Le problème de droit est **concret** : il nomme les parties et parle « d'argent ».","Le formuler de façon abstraite : « Une personne publique peut-elle s'opposer à la diffusion de son image saisie dans un lieu privé ? »"],["La solution place le **dispositif avant le motif**, et le motif est trop vague.","« Au motif que toute personne, quelle que soit sa notoriété…, la Cour casse et annule… »"]]}},{"box":"Recopier l'arrêt, mêler les prétentions aux faits, poser un problème concret avec le nom des parties, écrire le dispositif avant le motif. Relis chaque fiche avec cette liste avant de la rendre.","title":"Les quatre fautes les plus fréquentes","kind":"piege"}]}]}],"metho":[{"id":"caspratique","title":"Le cas pratique : la méthode","body":[{"p":"Le **cas pratique** est un exercice qui soumet à l'étudiant des **faits fictifs** posant des **problèmes de droit** qu'il est invité à résoudre. Il le place dans la situation d'un juriste consulté : relever les questions de droit que soulèvent les faits et leur apporter une réponse argumentée, fondée sur les règles en vigueur. L'objectif n'est pas de réciter le cours, mais de **raisonner** : appliquer une règle générale à une situation particulière. La résolution suit six étapes : les faits, la qualification, le problème, la règle, l'application et la solution."},{"h":"Le travail au brouillon"},{"ol":["**Lire l'énoncé deux fois**, la seconde fois crayon en main. Souligner ce qui compte juridiquement : les **dates** (elles commandent les délais), l'**âge** et la **qualité** des personnes (mineur, époux, commerçant, magistrat), les **lieux** (ils commandent la compétence des tribunaux), les **actes** accomplis (vente, reconnaissance, mariage), les **sommes** et la **question posée** à la fin de l'énoncé.","**Écarter le décor** : un détail pittoresque (le « luxueux manoir », le « mannequin en vogue ») n'a pas d'intérêt juridique, sauf s'il révèle un élément utile. Ne retenir que les faits **pertinents**, ceux qui serviront à vérifier si les conditions de la règle sont réunies ; ne jamais ajouter de faits ni d'hypothèses que l'énoncé ne contient pas : ce qui n'est pas dit ne doit pas être inventé.","**Qualifier les faits** : qualifier, c'est **nommer en termes juridiques**, exprimer les faits en termes abstraits pour les rattacher aux catégories prévues par la loi. « Elle ne donne plus de nouvelles » devient **absence** ; « une photo publiée sans son accord » devient **atteinte au droit à l'image**.","**Dégager les problèmes de droit** : d'une question posée en langage courant (« que peut-il faire ? », « quels sont ses droits ? »), tirer une ou plusieurs questions de droit précises ; une question par difficulté juridique, posée dans un **ordre logique** (la question préalable avant sa conséquence : la situation de l'épouse avant le remariage du mari). Plusieurs difficultés peuvent toutefois être **réunies en une seule question** lorsque leur résolution relève d'**une même règle de droit**.","**Rechercher les règles** : textes légaux et réglementaires (loi, numéro, article), jurisprudence, adage, doctrine ayant marqué le droit positif. Pour chaque règle, lister ses **conditions** : ce sont elles que l'on vérifiera une à une.","**Confronter** les faits à chaque condition, puis **arrêter la solution** avant de rédiger."]},{"h":"La structure du devoir : plusieurs problèmes"},{"table":{"h":["Partie","Contenu","Formule type"],"r":[["**Résumé des faits**","Les faits utiles, dans l'ordre chronologique, en quelques phrases, sans recopier l'énoncé","« Le 31 mars 2012, Mme X… »"],["**Qualification juridique des faits**","Le domaine juridique auquel se rattachent les faits","« Les faits ainsi présentés se rapportent à… »"],["**Énoncé des problèmes**","Les questions de droit, sous forme interrogative","« Ils posent les problèmes de droit suivants : … ? … ? »"],["**Annonce du plan**","L'ordre dans lequel les problèmes seront traités","« Nous allons résoudre ces problèmes dans l'ordre ainsi établi. »"]]}},{"box":"Il n'y a pas forcément autant de problèmes que de difficultés. Quand plusieurs difficultés se résolvent par **la même règle de droit**, on les réunit en **une seule question**, traitée en une seule fois : on évite ainsi de répéter la même règle d'une partie à l'autre. Exemple : la validité de deux actes passés par le même mineur se pose en un seul problème, puisqu'une seule règle, l'incapacité du mineur, permet de répondre aux deux.","title":"Regrouper les difficultés","kind":"cle"},{"p":"Puis chaque problème est traité sous un titre numéroté (**I**, **II**, **III**…), en six temps :"},{"table":{"h":["Étape","Contenu","Formule type"],"r":[["**1. L'intitulé**","Un titre court qui annonce la question","« I. La situation juridique de Mme X »"],["**2. Le rappel des faits**","Les seuls faits utiles à ce problème","« Mme X est sans nouvelles depuis… »"],["**3. L'énoncé du problème**","La question de droit à résoudre","« Quelle est donc la situation juridique de Mme X ? »"],["**4. La règle de droit**","Le texte exact, ses conditions, l'adage ou la jurisprudence","« Aux termes de l'article … de la loi n° …, … »"],["**5. L'application**","La confrontation des faits avec chaque condition de la règle","« En l'espèce, … »"],["**6. La solution**","La réponse nette au problème posé","« En conclusion, … » ; « En définitive, … »"]]}},{"box":"Pour chaque problème : « **En droit**, … » (la règle), « **En l'espèce**, … » (l'application aux faits), « **Par conséquent**, … » (la solution). C'est la même démarche que règle, application et solution, avec des mots d'articulation qui la rendent visible au correcteur.","title":"La formule du cours","kind":"cle"},{"p":"**Exemple du cours.** A achète un ordinateur à B, qui promet de le livrer sous dix jours. Un mois après la vente, l'ordinateur n'est toujours pas livré."},{"quote":"**Problème de droit.** Le vendeur qui n'exécute pas son obligation de délivrance dans le délai convenu peut-il être sanctionné ?"},{"quote":"**En droit**, la délivrance est le transport de la chose vendue en la puissance et possession de l'acheteur (article 1604 du Code civil). Selon l'article 1610, si le vendeur manque à faire la délivrance dans le temps convenu, l'acquéreur peut, à son choix, demander la résolution de la vente ou sa mise en possession, si le retard ne vient que du fait du vendeur ; il peut en outre obtenir des dommages et intérêts (article 1611)."},{"quote":"**En l'espèce**, B s'était engagé à livrer l'ordinateur dans un délai de dix jours. Un mois après la vente, la livraison n'a toujours pas eu lieu."},{"quote":"**Par conséquent**, B n'a pas exécuté son obligation de délivrance dans le délai convenu. A peut demander soit la livraison de l'ordinateur, soit la résolution de la vente, et dans les deux cas des dommages et intérêts."},{"box":"Le plan en deux parties et deux sous-parties (I, A, B ; II, A, B) est celui de la dissertation et du commentaire. Il n'est **pas autorisé** dans le cas pratique : on numérote les problèmes (I, II, III…), sans subdivisions A et B.","title":"Pas de plan I / A / B","kind":"piege"},{"h":"La structure du devoir : un seul problème"},{"p":"Lorsque les faits ne soulèvent qu'**un seul problème**, la méthode change : la rédaction se fait **en bloc**, sans introduction à part ni développement à part. On enchaîne :"},{"ol":["**Résumé des faits**.","**Qualification juridique des faits**.","**Énoncé du problème** à résoudre.","**Règle de droit** applicable.","**Application** de la règle aux faits (« En l'espèce… »).","**Solution**."]},{"box":"Pas de titre numéroté (I, II), pas d'annonce de plan ni de « rappel des faits » distinct : après le problème de droit, on enchaîne directement la règle, l'« en l'espèce » et la solution, en paragraphes liés par des transitions (« Par ailleurs », « Enfin », « En l'espèce », « De plus », « En somme »).","title":"Rédaction en bloc","kind":"cle"},{"h":"Les règles de rédaction"},{"ul":["**Une règle exacte** : citer le texte ivoirien précis (« article 6 de la loi n° 2022-885 du 23 novembre 2022 relative à l'absence et à la disparition »), et non une formule vague.","**Une définition légale complète** : lorsque la loi définit une notion, reproduire tous ses éléments, car ce sont eux que l'on vérifie un à un dans l'application. Exemple : l'absent est la personne qui a cessé de paraître au lieu de son domicile ou de sa résidence, sans nouvelles, de sorte que son existence est devenue incertaine (article 1er de la loi n° 2022-885).","**Une application réelle** : reprendre chaque condition de la règle et dire si elle est remplie, faits à l'appui. C'est la partie la plus valorisée.","**Une solution franche** : oui ou non, et à quelles conditions. Si un fait est incertain, raisonner par hypothèses (« si… alors… ; si au contraire… »).","**Répondre à la question posée** par la personne qui consulte : peut-il se remarier, obtenir réparation, saisir tel tribunal ?","**Ne jamais inventer de faits** ni modifier ceux de l'énoncé.","**Écrire simplement** : phrases courtes, au présent, paragraphes aérés."]},{"table":{"h":["Erreur fréquente","Bonne pratique"],"r":[["Recopier l'énoncé en guise de résumé","Résumer les seuls faits utiles, dans l'ordre chronologique"],["Réciter tout le cours sur la question","Ne citer que les règles utiles à la solution"],["Mélanger la règle et l'application","Énoncer la règle, puis l'appliquer « en l'espèce »"],["Oublier de conclure","Terminer chaque problème par une solution claire"],["Traiter la conséquence avant la question préalable","Classer les problèmes dans un ordre logique"]]}},{"h":"S'entraîner à qualifier les faits"},{"p":"**Qualifier, c'est nommer en termes juridiques** : exprimer les faits en termes abstraits pour les rattacher aux catégories prévues par la loi. Exercices du cours :"},{"table":{"h":["Les faits","La qualification juridique"],"r":[["Mme Konan lègue son véhicule à sa nièce dans son testament, deux mois avant son décès.","Un **legs** : libéralité à cause de mort, faite par testament, portant sur un bien meuble ; la nièce est **légataire**."],["L'étudiant Coulibaly loue une résidence au CROU d'Abidjan.","Un **contrat de bail** (louage d'immeuble à usage d'habitation) : Coulibaly est le **preneur**, le CROU le **bailleur**."],["La société Ivoire Agri vend du matériel agricole à la société SOGB pour 250 000 000 FCFA.","Une **vente commerciale** entre deux sociétés commerciales, régie par l'Acte uniforme OHADA relatif au droit commercial général."],["Koné, cycliste, est renversé par un véhicule lors d'une randonnée.","Un **accident de la circulation** : fait juridique qui engage la **responsabilité civile** du conducteur ; Koné est la **victime**."],["Roland s'introduit chez ses voisins en brisant la porte et dérobe des biens d'une valeur de 700 000 FCFA.","Un **vol** (soustraction frauduleuse de la chose d'autrui) **aggravé par l'effraction**, commis dans un lieu habité : une **infraction pénale**."]]}}]},{"id":"casexemple","title":"Le cas pratique : exemples rédigés","body":[{"p":"Deux copies modèles : l'affaire WERE-WERE, qui pose plusieurs problèmes, puis l'affaire MAINSMAINCE, qui n'en pose qu'un et se rédige en bloc."},{"h":"Exemple de rédaction : plusieurs problèmes"},{"quote":"**Résumé des faits.** Le 31 mars 2012, Mme WERE-WERE est confrontée à un mouvement insurrectionnel armé. Elle s'abrite et donne de ses nouvelles à son mari pendant sept jours. Profitant d'une accalmie, elle trouve refuge chez son frère. Depuis lors, son mari et ses enfants sont sans nouvelles d'elle. M. WERE-WERE souhaite se remarier."},{"quote":"**Qualification.** Les faits ainsi présentés se rapportent à l'incertitude sur l'existence de la personne physique."},{"quote":"**Problèmes.** Ils posent les problèmes de droit suivants : quelle est la situation juridique de Mme WERE-WERE ? M. WERE-WERE peut-il se remarier ?"},{"quote":"**Plan.** Nous allons résoudre ces problèmes dans l'ordre ainsi établi."},{"quote":"**I. La situation juridique de Mme WERE-WERE.** Depuis le 31 mars 2012, Mme WERE-WERE n'a plus donné de nouvelles à sa famille, après s'être abritée d'un mouvement insurrectionnel puis réfugiée chez son frère. Quelle est donc sa situation juridique ? Aux termes de l'article 1er de la loi n° 2022-885 relative à l'absence et à la disparition, l'absent est la personne qui a cessé de paraître au lieu de son domicile ou de sa résidence sans que l'on ait de ses nouvelles, de sorte que son existence est devenue incertaine. Selon l'article 13 de la même loi, le disparu est la personne qui a cessé de paraître à la suite de circonstances de nature à mettre sa vie en danger, sans que son corps ait pu être retrouvé. En l'espèce, Mme WERE-WERE a continué de donner de ses nouvelles pendant sept jours après les troubles, et elle a cessé de paraître alors qu'elle se trouvait en sécurité chez son frère : ses dernières nouvelles ne font pas suite à une situation de nature à mettre sa vie en danger. En conclusion, sa situation s'apparente à l'absence."},{"quote":"**II. Le remariage de M. WERE-WERE.** M. WERE-WERE, sans nouvelles de son épouse depuis 2012, souhaite se remarier. M. WERE-WERE peut-il se remarier ? Selon l'article 6 de la même loi, le mariage de l'absent se dissout à compter du jour où le jugement déclaratif d'absence est devenu définitif. En l'espèce, aucune démarche n'a été entamée pour faire déclarer l'absence. En définitive, M. WERE-WERE ne peut pas, à l'heure actuelle, se remarier ; il doit d'abord faire déclarer l'absence de son épouse."},{"h":"Exemple de rédaction : un seul problème"},{"p":"L'affaire MAINSMAINCE (atteinte à l'honneur d'un homme politique) ne soulève qu'un seul problème : elle se rédige donc en bloc."},{"quote":"**Résumé des faits.** M. MAINSMAINCE est un homme politique très connu. Malade, amaigri et épuisé, il se promène un soir au coucher du soleil, dans une tenue qui camoufle son corps. Un journaliste le reconnaît et publie dans le quotidien « Zié voit » un article intitulé « Homme politique et maladie du siècle », qui affirme que M. MAINSMAINCE est atteint du SIDA. L'article est illustré d'une photo prise le soir même à son insu, suivie de la légende : « Peut-on cacher le soleil de sa main ? ». En réalité, M. MAINSMAINCE souffre d'une tuberculose doublée d'un cancer de la peau. Choqué par ces écrits et par la parution de sa photo, il souhaite faire réparer l'atteinte portée à son honneur."},{"quote":"**Qualification juridique.** Les faits ainsi présentés se rapportent aux **droits de la personnalité**, plus précisément à la protection de l'**intégrité morale** de la personne : son honneur, sa vie privée et son image."},{"quote":"**Problème de droit.** Une personnalité publique faussement présentée par la presse comme atteinte d'une maladie, avec une photographie prise sans son consentement, peut-elle obtenir réparation de l'atteinte portée à son intégrité morale ?"},{"quote":"Selon l'article 90 de la loi n° 2017-867 du 27 décembre 2017 portant régime juridique de la presse, la **diffamation** est « toute allégation ou imputation d'un fait qui porte atteinte à l'honneur ou à la considération de la personne ou du corps auquel le fait est imputé »."},{"quote":"Par ailleurs, toute personne, même connue du public, a droit au **respect de sa vie privée**, dont fait partie son **état de santé**, et au **respect de son image** : sa photographie ne peut être publiée sans son consentement."},{"quote":"Enfin, aux termes de l'article 1382 du Code civil, « tout fait quelconque de l'homme, qui cause à autrui un dommage, oblige celui par la faute duquel il est arrivé à le réparer »."},{"quote":"En l'espèce, le journal attribue à M. MAINSMAINCE une maladie dont il n'est pas atteint, et la légende moqueuse laisse entendre qu'il dissimule un fait honteux. Cette imputation est **fausse** et porte atteinte à son honneur et à sa considération : elle constitue une **diffamation**. Le fait étant faux, le journaliste ne peut se défendre en invoquant sa vérité."},{"quote":"De plus, l'article divulgue des informations sur l'**état de santé** de M. MAINSMAINCE, ce qui porte atteinte à sa **vie privée**, et publie sa **photographie**, prise à son insu au cours d'une promenade privée, ce qui porte atteinte à son **droit à l'image**. Sa notoriété politique autorise la presse à commenter ses activités publiques, non à exposer sa santé et son corps. Ces fautes lui causent un **préjudice moral** certain."},{"quote":"En somme, M. MAINSMAINCE peut agir sur deux plans. **Au pénal**, il porte plainte pour diffamation contre le journaliste et le directeur de publication, dans les délais brefs prévus par la loi sur la presse. **Au civil**, sur le fondement de l'article 1382 du Code civil, il obtient des **dommages et intérêts**, le **retrait de l'article** et de tous les supports de diffusion, ainsi que la publication d'un **droit de réponse**."},{"box":"Chaque paragraphe a une fonction et une seule. Le correcteur doit pouvoir repérer d'un coup d'œil la règle, l'« en l'espèce » et la solution.","title":"À retenir","kind":"cle"}]},{"id":"fichedecision","title":"La fiche de décision","body":[{"p":"Commenter une décision, c'est d'abord la **comprendre** (ce qu'elle décide et pourquoi), puis l'**apprécier** (est-elle fondée ?) et en mesurer la **portée** (quelle est son influence ?). Tout commence par la **fiche de décision**, qui en est le squelette."},{"h":"Lire une décision de la Cour de cassation"},{"table":{"h":["Élément","Où le trouver","Ce qu'il apprend"],"r":[["**Le visa**","« Vu l'article… » ou « Vu le principe… », en tête","Le texte ou le principe sur lequel la Cour fonde sa décision ; sa présence annonce souvent une **cassation**"],["**Les faits et la procédure**","Les premiers « Attendu que… »","Ce qui s'est passé et le parcours de l'affaire"],["**La décision attaquée**","« Attendu que l'arrêt attaqué a… aux motifs que… »","La solution des juges du fond et leurs raisons"],["**Le moyen du pourvoi**","« Alors, selon le moyen, que… »","La thèse de l'auteur du pourvoi"],["**La réponse de la Cour**","« Mais attendu que… » (rejet) ; « Attendu cependant que… » (cassation)","Les **motifs** de la Cour : le cœur de la décision"],["**Le dispositif**","Après « **Par ces motifs** »","Ce que la Cour décide : rejet, ou cassation avec ou sans renvoi"]]}},{"h":"La fiche de décision en cinq étapes"},{"table":{"h":["Étape","Contenu","Conseil"],"r":[["**1. Les références**","**Nature** de la décision (arrêt de cassation, de rejet, jugement), **juridiction** et chambre, **date**, **parties** opposées","« Il s'agit d'un arrêt de cassation rendu par la première chambre civile de la Cour de cassation le…, dans un litige opposant X à Y. »"],["**2. Les faits**","Les faits matériels, dans l'ordre chronologique, avant toute procédure","Les faits sont **différents des prétentions** : ne pas y mettre ce que réclament les parties. Ne jamais recopier les « **que** » de l'arrêt (« Attendu que… ; que… ») : on raconte les faits avec ses propres mots, au présent, en observateur extérieur"],["**3. La procédure**","Le parcours judiciaire : saisine du premier juge, décision, appel, décision d'appel et ses motifs, pourvoi et sa demande","Préciser **qui** agit, **devant quelle juridiction**, **pour demander quoi**, et le sens de chaque décision"],["**4. Le problème de droit**","La question de droit posée à la **dernière juridiction saisie**","Question **abstraite** : le nom d'aucune partie ne doit y apparaître"],["**5. La solution**","La réponse de la dernière juridiction saisie : ses **motifs** puis son **dispositif**","Dans l'arrêt, les **motifs** commencent à « **Attendu cependant que** » (cassation) ou « Mais attendu que » (rejet) et vont jusqu'à « **Par ces motifs** » ; le **dispositif** suit : « **casse et annule** » ou « rejette le pourvoi ». Dans la fiche, le **motif est toujours rédigé avant le dispositif**"]]}},{"box":"Dans l'arrêt, la Cour donne d'abord ses raisons (« Attendu cependant que… ») puis sa décision (« Par ces motifs : casse et annule… »). Dans la fiche, on garde cet ordre : **d'abord le motif, ensuite le dispositif**. Formule type : « **Au motif que** [raison donnée par la Cour], la Cour de cassation **casse et annule** l'arrêt de la cour d'appel de… et renvoie les parties devant la cour d'appel de… »","title":"Le motif avant le dispositif","kind":"piege"},{"h":"Dégager le problème de droit"},{"p":"Deux méthodes, à combiner :"},{"ol":["**La confrontation des thèses** : opposer ce que soutient chaque partie, ou ce qu'ont jugé les juridictions successives. Le problème naît du point de désaccord.","**L'anticipation de la solution** : partir de la réponse de la dernière juridiction et se demander à quelle question elle répond."]},{"p":"La bonne démarche consiste à **faire la confrontation**, puis à **vérifier** que la solution finale répond bien à la question formulée."},{"table":{"h":["Formulation","Appréciation"],"r":[["« Mme Segers peut-elle obtenir la majoration pour ses jumeaux ? »","**Mauvaise** : concrète, nomme une partie"],["« Les enfants simplement conçus ont-ils la personnalité juridique ? »","**Mauvaise** : trop large, hors du contexte du litige"],["« Une police d'assurance-décès qui majore le capital pour chaque enfant à charge vivant au foyer au moment du décès doit-elle prendre en compte les enfants simplement conçus à cette date ? »","**Bonne** : abstraite, précise, et la solution y répond"]]}},{"h":"Notions et abréviations utiles"},{"ul":["Il n'existe qu'**une seule Cour de cassation par pays**. Elle est **juge du droit** : elle vérifie l'application de la loi, sans rejuger les faits. Le **tribunal** et la **cour d'appel** sont des **juridictions du fond** : ils jugent les faits et le droit.","Exceptionnellement, la Cour de cassation statue elle-même **sur le fond** : quand elle casse **sans renvoi** parce qu'il ne reste rien à juger, ou quand elle statue **sur évocation**, c'est-à-dire qu'après avoir cassé, elle juge elle-même l'affaire en fait et en droit. La CCJA de l'OHADA statue toujours ainsi après cassation.","Une décision peut aller directement du tribunal à la Cour de cassation : c'est le cas lorsque le tribunal a statué **en premier et dernier ressort** (aucun appel possible).","Une **cassation avec renvoi** remet les parties dans l'état où elles se trouvaient avant la décision cassée et les renvoie devant une autre juridiction de même nature (une autre cour d'appel)."]},{"table":{"h":["Abréviation","Sens"],"r":[["**Cass. civ. 1re**","Cour de cassation, première chambre civile"],["**Cass. crim.** / **Cass. soc.** / **Cass. com.**","Chambre criminelle / sociale / commerciale"],["**Cass. ass. plén.** / **Ch. mixte**","Assemblée plénière / chambre mixte"],["**CA**","Cour d'appel"],["**TPI** / **Trib.**","Tribunal de première instance / tribunal"],["**CCJA**","Cour commune de justice et d'arbitrage de l'OHADA"],["**Bull. civ.** / **D.** / **JCP**","Bulletin civil de la Cour de cassation / Recueil Dalloz / Semaine juridique (recueils où l'arrêt est publié)"]]}},{"h":"Exemple de fiche de décision"},{"quote":"**Références.** Il s'agit d'un arrêt de cassation rendu par la première chambre civile de la Cour de cassation française le 10 décembre 1985, dans un litige opposant Mme Segers à la compagnie d'assurance Euravie."},{"quote":"**Faits.** Bernard Segers adhère à une assurance-groupe qui garantit, en cas de décès, un capital majoré de 30 % par enfant à charge vivant au foyer. Il décède le 1er mars 1980 ; son épouse met au monde des jumeaux le 24 mai 1980. L'assureur refuse la majoration pour ces enfants, non nés au jour du décès."},{"quote":"**Procédure.** Mme Segers assigne l'assureur en paiement d'un complément de 108 062 francs. La cour d'appel de Paris rejette sa demande le 24 mai 1984. Toujours insatisfaite, Mme Segers forme un pourvoi en cassation en invoquant la règle *infans conceptus*."},{"quote":"**Problème de droit.** Une police d'assurance-décès qui majore le capital pour chaque enfant à charge vivant au foyer au moment du décès doit-elle prendre en compte les enfants simplement conçus à cette date ?"},{"quote":"**Solution.** Au motif que la détermination des enfants à charge doit respecter le principe selon lequel l'enfant conçu est réputé né chaque fois qu'il y va de son intérêt, la Cour de cassation casse et annule l'arrêt de la cour d'appel de Paris et renvoie les parties devant la cour d'appel de Versailles."}]},{"id":"commentaire","title":"Le commentaire de décision","body":[{"p":"La fiche de décision est le squelette ; le commentaire en est la chair. Il s'agit d'expliquer la décision, de l'apprécier et d'en mesurer l'influence."},{"p":"Le commentaire proprement dit se rédige ensuite comme une dissertation, avec un **plan en deux parties et deux sous-parties** (I, A, B ; II, A, B), cette fois obligatoire."},{"table":{"h":["Partie","Contenu"],"r":[["**Introduction**","Une phrase d'accroche liée au thème ; la fiche de décision sous forme rédigée et condensée (faits, procédure, prétentions) ; le **problème de droit** ; la **solution** en une phrase ; l'**annonce du plan**"],["**I. Le sens de la décision**","Ce que décide la juridiction et sur quel fondement : expliquer la règle appliquée, ses conditions, son raisonnement"],["**II. La valeur et la portée**","Apprécier la solution (est-elle conforme aux textes, juste, cohérente ?) et mesurer sa portée : arrêt de principe ou d'espèce, publication, suites, solution en droit ivoirien"]]}},{"ul":["Les **titres** doivent être précis et tirés de la décision, jamais génériques (« I. Le sens », « II. La portée » ne suffisent pas).","Chaque partie s'ouvre sur un **chapeau** qui annonce les sous-parties ; une **transition** relie le I au II.","Ne jamais **paraphraser** l'arrêt : on l'explique et on le discute, en citant ses formules entre guillemets."]},{"h":"Sens, valeur et portée"},{"table":{"h":["Question","Ce que tu cherches"],"r":[["**Sens**","Que décide la juridiction, et sur quel fondement ? Quelle règle applique-t-elle, et comment l'interprète-t-elle ?"],["**Valeur**","La solution est-elle juridiquement fondée ? Est-elle opportune, cohérente avec les textes et la jurisprudence antérieure ?"],["**Portée**","Quelle influence aura-t-elle ? Arrêt de principe ou d'espèce, revirement ou confirmation, effet sur le droit ivoirien."]]}},{"box":"Un **arrêt de principe** pose une règle générale, souvent dans un attendu de principe placé en tête, au visa d'un texte ou d'un principe. Un **arrêt d'espèce** tranche un cas particulier au vu de ses faits et n'a qu'une portée limitée.","title":"Principe ou espèce","kind":"cle"},{"h":"Les erreurs à éviter"},{"ul":["Raconter l'arrêt au lieu de le commenter.","Faire un commentaire « à côté » : une dissertation sur le thème qui oublie la décision.","Plaquer des titres passe-partout (« Le sens », « La portée »).","Oublier de citer la décision entre guillemets pour appuyer chaque idée.","Confondre la thèse du demandeur au pourvoi avec la solution de la Cour."]},{"h":"Exemple : plan de l'arrêt du 10 décembre 1985"},{"p":"**Problème de droit.** Une police d'assurance-décès qui majore le capital pour chaque enfant à charge vivant au foyer de l'assuré au moment du décès doit-elle prendre en compte les enfants simplement conçus à cette date ?"},{"p":"**Plan de commentaire proposé**"},{"ul":["I. La reconnaissance d'un droit à l'enfant simplement conçu (A. Un principe général du droit ; B. Appliqué à l'assurance-décès)","II. Les conditions de cette reconnaissance (A. L'intérêt de l'enfant ; B. La naissance de l'enfant vivant)"]},{"box":"La Cour de cassation érige l'adage *infans conceptus* en **principe général du droit** et l'applique au-delà des successions et des libéralités, ici à un contrat d'assurance. En droit ivoirien, le même raisonnement vaut ; depuis 2019, il suffit que l'enfant naisse vivant.","title":"Portée de la décision","kind":"marge"}]}]};
  const meth = get("methode"); if (meth) { meth.title = "La dissertation juridique"; meth.body = N.dissBody; }
  const m = id => N.metho.find(l => l.id === id), a = id => N.atel.find(l => l.id === id);
  M_METHO.lessons = [N.intro, a("atelier1"), meth, N.dissexo, get("sujet"), get("corrige"), a("atelier2"), m("caspratique"), m("casexemple"), N.casexo, a("atelier3"), m("fichedecision"), m("commentaire"), N.ficheexo, a("atelier4")].filter(Boolean);
})();
M_METHO.quiz.push(...[{"q":"Dans un cas pratique, le plan I / A / B est…","a":["peu adapté : on numérote les problèmes I, II, III","obligatoire","exigé pour chaque problème","réservé aux cas à un seul problème"],"c":0,"e":"On numérote les problèmes I, II, III, sans nécessairement de subdivisions A et B."},{"q":"Quand le cas pratique ne pose qu'un seul problème…","a":["la rédaction se fait en bloc","on fait deux parties","on supprime le résumé des faits","on commence par la solution"],"c":0,"e":"Pas d'introduction ni de développement séparés."},{"q":"Les cinq étapes de la fiche de décision sont…","a":["nature de la décision, faits, procédure, problème de droit, solution","faits, prétentions, plan, solution, portée","introduction, I, II, conclusion, portée","visa, chapeau, motifs, dispositif, renvoi"],"c":0,"e":"La solution comprend les motifs puis le dispositif."},{"q":"Dans la fiche de décision, le problème de droit doit être…","a":["abstrait, sans nom des parties","formulé avec le nom des parties","une citation de l'arrêt","une affirmation"],"c":0,"e":"Il est posé à la dernière juridiction saisie."},{"q":"Dans un arrêt, « Par ces motifs » sépare…","a":["les motifs du dispositif","les faits de la procédure","le visa du chapeau","le moyen de la réponse"],"c":0,"e":"Avant : les motifs ; après : le dispositif."},{"q":"« Attendu cependant que… » annonce généralement…","a":["une cassation","un rejet","un renvoi pour suspicion","une irrecevabilité"],"c":0,"e":"« Mais attendu que… » annonce un rejet."},{"q":"Selon le cours, la conclusion d'une dissertation juridique est…","a":["facultative","obligatoire","interdite","réservée au commentaire"],"c":0,"e":"Contrairement à l'introduction et au développement, elle est facultative."},{"q":"Les deux exigences de la dissertation sont…","a":["l'exhaustivité et la rigueur","la longueur et l'élégance","la mémoire et la vitesse","l'originalité et l'humour"],"c":0,"e":"Tous les aspects importants du sujet, sans hors-sujet."},{"q":"La formule recommandée pour résoudre chaque problème d'un cas pratique est…","a":["En droit… En l'espèce… Par conséquent…","Premièrement… Deuxièmement…","Thèse… Antithèse… Synthèse…","Introduction… Conclusion…"],"c":0,"e":"La règle, l'application aux faits, la solution."},{"q":"Combien d'exercices le cours de méthodologie étudie-t-il ?","a":["Quatre : dissertation, cas pratique, commentaire d'arrêt, commentaire de texte","Deux","Trois","Six"],"c":0,"e":"Ce sont les quatre exercices pratiqués en faculté de droit."}]);
M_METHO.cards.push(...[["Cas pratique (plusieurs problèmes)","Résumé des faits, qualification, problèmes, plan ; puis pour chaque problème : intitulé, faits, problème, règle, application, solution"],["Cas pratique (un seul problème)","Rédaction en bloc : résumé, qualification, problème, règle, application, solution"],["Fiche de décision","Nature de la décision, faits, procédure, problème de droit, solution"],["Dispositif","Ce que décide la juridiction, après « Par ces motifs »"],["Visa","Texte ou principe sur lequel la Cour de cassation fonde sa décision"],["Sur évocation","La Cour, après cassation, juge elle-même l'affaire au fond"],["Exhaustivité","Exigence de la dissertation : aborder tous les aspects importants du sujet"],["Rigueur","Exigence de la dissertation : ni hors-sujet, ni développements qui ne répondent pas au problème et aux titres"],["Qualifier","Nommer les faits en termes juridiques pour les rattacher à une catégorie du droit"],["Disserere","Racine latine de « dissertation » : exposer des raisonnements liés les uns aux autres"]]);
