M_EN.title = "Anglais juridique";
M_EN.subtitle = "Legal English : le droit en situation, dialogues et prononciation";
M_EN.lessons = [{"id":"welcome","title":"Unit 1 · Welcome to Law School","body":[{"illus":"campus","cap":"First day at the Faculty of Law"},{"p":"Premier jour à la faculté : on se présente, on salue un professeur, on parle de ses études. Le présent simple sert à dire **qui l'on est** et **ce que l'on fait d'habitude**."},{"envocab":[["🎓","a law student","un étudiant en droit","I am a first-year law student."],["🏛","the Faculty of Law","la faculté de droit","The Faculty of Law is next to the library."],["📚","a lecture","un cours magistral","The lecture on civil law starts at eight."],["📝","a tutorial","des travaux dirigés (TD)","We have a tutorial on Thursday."],["👨🏾‍🏫","a lecturer","un enseignant, un chargé de cours","Our lecturer explains the cases very clearly."],["📅","a semester","un semestre","The first semester ends in January."],["✍️","to take notes","prendre des notes","I always take notes in class."],["🗓","a timetable","un emploi du temps","Let me check the timetable."]]},{"endialog":{"situation":"Devant l'amphithéâtre, Awa rencontre Moussa, puis leur professeur, Dr Kouadio.","lines":[["Awa","#b5651d","Hi! Are you in first year too?","Salut ! Tu es aussi en première année ?"],["Moussa","#0e6b4f","Yes, I am. My name is Moussa. I'm from Bouaké.","Oui. Je m'appelle Moussa. Je viens de Bouaké."],["Awa","#b5651d","Nice to meet you, Moussa. I'm Awa, from Abidjan. Why do you study law?","Enchantée, Moussa. Moi c'est Awa, d'Abidjan. Pourquoi étudies-tu le droit ?"],["Moussa","#0e6b4f","I want to become a judge. And you?","Je veux devenir juge. Et toi ?"],["Awa","#b5651d","I'd like to be a lawyer. Look, here comes Dr Kouadio.","J'aimerais être avocate. Regarde, voici le Dr Kouadio."],["Dr Kouadio","#7a3fb3","Good morning, everyone. Welcome to the Faculty of Law.","Bonjour à tous. Bienvenue à la faculté de droit."],["Awa","#b5651d","Good morning, sir. Excuse me, where is the civil law lecture?","Bonjour, monsieur. Excusez-moi, où a lieu le cours de droit civil ?"],["Dr Kouadio","#7a3fb3","In Lecture Hall B, at eight o'clock. Don't forget to take notes!","À l'amphithéâtre B, à huit heures. N'oubliez pas de prendre des notes !"]]}},{"h":"Se présenter en public : le texte modèle du cours"},{"ol":["**Greeting** : *Good morning, everyone.*","**Thanks** : *First of all, I would like to thank you for giving me the opportunity to introduce myself.*","**Identity** : *My name is… I'm from…*","**Profile** : *I am a first-year law student at the Muslim University of Africa.*","**Values and hobbies** : *I believe in… In my free time, I enjoy…*","**Goals** : *My goal is to become…*","**Closing** : *Thank you for your attention. It is a pleasure to meet you all.*"]},{"sents":"text","paras":[0,4,7,9]},{"h":"Grammaire : le présent simple"},{"table":{"h":["Forme","Exemple","Français"],"r":[["**Affirmation**","She **studies** law. I **live** in Cocody.","Elle étudie le droit. J'habite à Cocody."],["**Négation**","He **does not (doesn't) work** on Sundays.","Il ne travaille pas le dimanche."],["**Question**","**Do** you **like** criminal law?","Aimes-tu le droit pénal ?"]]}},{"box":"À la 3e personne du singulier, on ajoute **-s** : *the judge decide**s***, *the lawyer argue**s***. Après *does*, le verbe reprend sa forme simple : *Does he work?*","title":"À retenir","kind":"cle"},{"h":"À toi de jouer"},{"p":"Présente-toi en cinq phrases à un camarade : nom, ville, études, matière préférée, projet professionnel. Puis pose-lui trois questions au présent simple."},{"corrige":[{"quote":"*Hello, my name is Ibrahim. I'm from Daloa. I'm a first-year law student at the Muslim University of Africa. My favorite subject is constitutional law. I want to become a prosecutor.* — *Where are you from? What is your favorite subject? Do you live on campus?*"}]}]},{"id":"whatislaw","title":"Unit 2 · What is law?","body":[{"illus":"justice","cap":"Law: rules, authority, enforcement, justice"},{"p":"Le cours du 21 octobre : la définition du droit en anglais, ses caractères et ses grandes branches. Écoute chaque phrase, puis répète-la."},{"sents":"lawtext","paras":[0,3,8],"labels":["Definition of law","Characteristics of law","Types of law"]},{"table":{"h":["Characteristic","Français"],"r":[["**Rules**","Le droit est fait de règles qui encadrent la conduite humaine."],["**Authority**","Les lois sont établies ou reconnues par des autorités légitimes."],["**Enforcement**","Les tribunaux et institutions compétentes les font appliquer."],["**Justice**","Le droit protège les droits et promeut l'équité."],["**Sanctions**","Violer la loi entraîne des sanctions."]]}},{"envocab":[["⚖","criminal law","le droit pénal","Criminal law deals with crimes and punishment."],["🤝","civil law","le droit civil","Civil law deals with disputes between individuals."],["🏛","constitutional law","le droit constitutionnel","Constitutional law governs the powers of the State."],["🏢","administrative law","le droit administratif","Administrative law regulates public authorities."],["🌍","international law","le droit international","International law governs relations between States."],["💼","business law","le droit des affaires","OHADA harmonizes business law in Africa."],["📜","to enforce","faire appliquer","The police enforce the law."],["💬","to settle a dispute","régler un litige","Courts settle disputes."]]},{"endialog":{"situation":"Après le cours, Moussa pose des questions au Dr Kouadio sur les branches du droit.","lines":[["Moussa","#0e6b4f","Sir, what is the difference between civil law and criminal law?","Monsieur, quelle est la différence entre le droit civil et le droit pénal ?"],["Dr Kouadio","#7a3fb3","Good question. Civil law deals with disputes between private persons, for example a contract or a divorce.","Bonne question. Le droit civil traite des litiges entre personnes privées, par exemple un contrat ou un divorce."],["Moussa","#0e6b4f","And criminal law?","Et le droit pénal ?"],["Dr Kouadio","#7a3fb3","Criminal law deals with offenses against society, like theft or murder. The State prosecutes the offender.","Le droit pénal traite des infractions contre la société, comme le vol ou le meurtre. L'État poursuit l'auteur."],["Moussa","#0e6b4f","So a car accident can be civil and criminal at the same time?","Donc un accident de voiture peut être à la fois civil et pénal ?"],["Dr Kouadio","#7a3fb3","Exactly. The victim can claim damages, and the driver can be prosecuted.","Exactement. La victime peut demander des dommages-intérêts, et le conducteur peut être poursuivi."]]}},{"box":"*Rules* = règle générale et abstraite ; *authority* = règle étatique ; *enforcement* et *sanctions* = règle obligatoire et coercitive. Ce sont les caractères de la règle de droit vus en introduction au droit.","title":"Lien avec le cours de droit","kind":"cle"},{"h":"À toi de jouer"},{"p":"Classe chaque situation dans la bonne branche du droit : (1) a theft at the market ; (2) a dispute over unpaid rent ; (3) the election of the President ; (4) a trade agreement between two States ; (5) a mayor refuses a building permit."},{"corrige":[{"ol":["Criminal law.","Civil law.","Constitutional law.","International law.","Administrative law."]}]},{"words":"law"}]},{"id":"professions","title":"Unit 3 · The legal professions","body":[{"illus":"professions","cap":"Who does what in the justice system?"},{"p":"Qui fait quoi dans la justice ? On apprend les métiers du droit et les verbes qui décrivent leur rôle."},{"envocab":[["⚖","a judge","un juge","The judge decides the case impartially."],["💼","a lawyer / an attorney","un avocat","The lawyer advises and defends her client."],["🗂","a prosecutor","un procureur","The prosecutor represents society."],["🖋","a court clerk","un greffier","The court clerk keeps the records of the hearing."],["📜","a notary","un notaire","A notary drafts deeds and certifies signatures."],["✉","a bailiff","un commissaire de justice","The bailiff serves the summons."],["🔎","an investigating judge","un juge d'instruction","The investigating judge gathers evidence."],["🎓","a legal adviser","un juriste conseil","Companies hire legal advisers."]]},{"endialog":{"situation":"Au salon des métiers de l'université, Awa interroge Maître Bamba, avocate au barreau d'Abidjan.","lines":[["Awa","#b5651d","Good afternoon, ma'am. Could you tell me about your job?","Bonjour, madame. Pourriez-vous me parler de votre métier ?"],["Maître Bamba","#23468f","Of course. I'm a lawyer. I advise my clients and I represent them in court.","Bien sûr. Je suis avocate. Je conseille mes clients et je les représente en justice."],["Awa","#b5651d","How do you become a lawyer in Côte d'Ivoire?","Comment devient-on avocat en Côte d'Ivoire ?"],["Maître Bamba","#23468f","After your law degree, you pass the bar exam, then you do a traineeship before joining the bar.","Après la licence et le master, on réussit l'examen du barreau, puis on fait un stage avant l'inscription au tableau."],["Awa","#b5651d","What's the difference between you and a prosecutor?","Quelle est la différence entre vous et un procureur ?"],["Maître Bamba","#23468f","The prosecutor is a magistrate. He represents society and brings criminal charges. I defend private interests.","Le procureur est un magistrat. Il représente la société et engage les poursuites. Moi, je défends des intérêts privés."],["Awa","#b5651d","Thank you so much. That's very helpful!","Merci beaucoup. C'est très utile !"]]}},{"h":"Dire ce que fait chaque professionnel"},{"table":{"h":["Professional","Verb","Exemple"],"r":[["judge","to decide, to rule, to sentence","The judge **sentenced** him to two years."],["lawyer","to advise, to defend, to plead","She **pleads** before the court of appeal."],["prosecutor","to prosecute, to charge","The prosecutor **charged** him with theft."],["clerk","to record, to keep files","The clerk **records** the hearing."],["notary","to draft, to certify","The notary **drafts** the deed of sale."]]}},{"box":"En anglais américain, *attorney* = avocat. En Grande-Bretagne, le *barrister* plaide et le *solicitor* conseille. En Côte d'Ivoire, un seul métier : l'**avocat** (*lawyer*).","title":"Bon à savoir","kind":"marge"},{"h":"À toi de jouer"},{"p":"Complète : (1) The ___ represents society in criminal cases. (2) The ___ keeps the records of the court. (3) A ___ drafts and certifies deeds. (4) The ___ serves documents and enforces judgments."},{"corrige":[{"p":"(1) prosecutor ; (2) court clerk ; (3) notary ; (4) bailiff."}]}]},{"id":"courts","title":"Unit 4 · The court system of Côte d'Ivoire","body":[{"illus":"courts","cap":"Three high courts since the 2020 reform"},{"p":"On décrit l'organisation judiciaire ivoirienne en anglais, et on apprend la **voix passive**, très fréquente dans les textes juridiques."},{"sents":"read","paras":[0,3,6,9]},{"envocab":[["🏛","the Court of Cassation","la Cour de cassation","The Court of Cassation only reviews points of law."],["🏢","the Council of State","le Conseil d'État","The Council of State hears administrative cases."],["💰","the Court of Auditors","la Cour des comptes","The Court of Auditors controls public finances."],["📜","the Constitutional Council","le Conseil constitutionnel","The Constitutional Council reviews laws."],["📈","a court of appeal","une cour d'appel","There are courts of appeal in Abidjan, Bouaké and Daloa."],["⚖","a court of first instance","un tribunal de première instance","Most cases begin in a court of first instance."],["🔁","to appeal","faire appel","The losing party may appeal."],["🧭","jurisdiction","la compétence","This court has no jurisdiction over the case."]]},{"endialog":{"situation":"Un étudiant étranger, Tom, demande à Moussa comment fonctionne la justice ivoirienne.","lines":[["Tom","#1f5f8b","Is there a Supreme Court in Côte d'Ivoire?","Y a-t-il une Cour suprême en Côte d'Ivoire ?"],["Moussa","#0e6b4f","Not anymore. Since the 2020 reform, it has been replaced by three high courts.","Plus maintenant. Depuis la réforme de 2020, elle est remplacée par trois hautes juridictions."],["Tom","#1f5f8b","Which ones?","Lesquelles ?"],["Moussa","#0e6b4f","The Court of Cassation, the Council of State and the Court of Auditors.","La Cour de cassation, le Conseil d'État et la Cour des comptes."],["Tom","#1f5f8b","And if I lose my case in a court of first instance?","Et si je perds mon procès devant un tribunal de première instance ?"],["Moussa","#0e6b4f","You can appeal. Your case is then heard again by a court of appeal.","Tu peux faire appel. Ton affaire est alors rejugée par une cour d'appel."],["Tom","#1f5f8b","And after that?","Et ensuite ?"],["Moussa","#0e6b4f","You can go to the Court of Cassation, but it only checks whether the law was correctly applied.","Tu peux saisir la Cour de cassation, mais elle vérifie seulement si la loi a été bien appliquée."]]}},{"h":"Grammaire : la voix passive"},{"table":{"h":["Actif","Passif"],"r":[["The court of appeal **hears** the case again.","The case **is heard** again by the court of appeal."],["Parliament **passed** the law in 2019.","The law **was passed** by Parliament in 2019."],["The judge **will deliver** the ruling tomorrow.","The ruling **will be delivered** tomorrow."]]}},{"box":"Passif = **be** conjugué + **participe passé**. On l'emploie quand l'action compte plus que son auteur : *The decision was quashed* (la décision a été cassée).","title":"À retenir","kind":"cle"},{"h":"À toi de jouer"},{"p":"Mets au passif : (1) The Constitutional Council reviews the law. (2) The Court of Cassation quashed the judgment. (3) The President promulgates laws."},{"corrige":[{"ol":["The law is reviewed by the Constitutional Council.","The judgment was quashed by the Court of Cassation.","Laws are promulgated by the President."]}]}]},{"id":"courtroom","title":"Unit 5 · In the courtroom","body":[{"illus":"courtroom","cap":"A criminal hearing"},{"p":"Une audience pénale : qui parle, quand et comment. On apprend les formules de l'audience et le vocabulaire du procès."},{"envocab":[["⚖","a trial","un procès","The trial starts on Monday."],["🗓","a hearing","une audience","The hearing was postponed."],["🧑🏾","the defendant","le prévenu, l'accusé","The defendant pleads not guilty."],["👁","a witness","un témoin","The witness saw the accident."],["🔎","evidence","les preuves","There is not enough evidence."],["⚖","guilty / not guilty","coupable / non coupable","The court found him guilty."],["🔒","a sentence","une peine","He received a suspended sentence."],["💵","a fine","une amende","She was ordered to pay a fine."],["✅","to acquit","relaxer, acquitter","The court acquitted the defendant."],["🗣","Your Honor","Monsieur le Président (au juge)","Yes, Your Honor."]]},{"endialog":{"situation":"Tribunal de première instance d'Abidjan-Plateau. M. Yao est poursuivi pour vol de téléphone.","lines":[["Judge","#7a2e2e","The court is now in session. Mr. Yao, you are charged with theft. How do you plead?","L'audience est ouverte. Monsieur Yao, vous êtes poursuivi pour vol. Que plaidez-vous ?"],["Mr. Yao","#b5651d","Not guilty, Your Honor.","Non coupable, Monsieur le Président."],["Judge","#7a2e2e","Prosecutor, you may call your first witness.","Monsieur le procureur, vous pouvez appeler votre premier témoin."],["Prosecutor","#9e2e46","Thank you, Your Honor. Mrs. Koné, what did you see on March 3rd?","Merci, Monsieur le Président. Madame Koné, qu'avez-vous vu le 3 mars ?"],["Mrs. Koné","#5a6b2e","I saw a man take a phone from my shop and run away.","J'ai vu un homme prendre un téléphone dans ma boutique et s'enfuir."],["Defense lawyer","#23468f","Objection, Your Honor! The witness cannot identify my client: the shop was dark.","Objection, Monsieur le Président ! Le témoin ne peut pas identifier mon client : la boutique était sombre."],["Judge","#7a2e2e","Objection sustained. Please answer only what you saw clearly, madam.","Objection retenue. Répondez seulement sur ce que vous avez vu clairement, madame."],["Judge","#7a2e2e","The case is adjourned. The ruling will be delivered on April 10th.","L'affaire est mise en délibéré. La décision sera rendue le 10 avril."]]}},{"h":"Les formules de l'audience"},{"table":{"h":["English","Français"],"r":[["*The court is now in session.*","L'audience est ouverte."],["*How do you plead?*","Que plaidez-vous ? (coupable ou non coupable)"],["*Objection sustained / overruled.*","Objection retenue / rejetée."],["*Do you swear to tell the truth?*","Jurez-vous de dire la vérité ?"],["*The case is adjourned.*","L'affaire est renvoyée / mise en délibéré."],["*The court finds the defendant guilty.*","Le tribunal déclare le prévenu coupable."]]}},{"box":"« Sentence » a deux sens : **une peine** (*a prison sentence*) et **une phrase** (*write a sentence*). Au tribunal, c'est toujours la peine.","title":"Piège","kind":"piege"},{"h":"À toi de jouer"},{"p":"Par trois, jouez la scène : un juge, un procureur, un avocat. Le prévenu est poursuivi pour conduite sans permis. Utilisez au moins quatre formules du tableau."},{"corrige":[{"quote":"*Judge: The court is now in session. Mr. Diallo, you are charged with driving without a license. How do you plead? — Mr. Diallo: Guilty, Your Honor. — Prosecutor: I ask the court to impose a fine. — Defense lawyer: My client is a first offender, Your Honor. — Judge: The court finds the defendant guilty and orders him to pay a fine of 50,000 CFA francs.*"}]}]},{"id":"police","title":"Unit 6 · At the police station","body":[{"illus":"police","cap":"Police custody and the right to a lawyer"},{"p":"La procédure pénale commence souvent au commissariat : interpellation, garde à vue, audition. On apprend à exprimer l'obligation et la permission avec les **verbes modaux**."},{"envocab":[["✋","to arrest","arrêter, interpeller","The police arrested two suspects."],["🧑🏾","a suspect","un suspect","The suspect denies everything."],["🔒","police custody","la garde à vue","He was held in police custody overnight."],["📋","a statement","une déposition, une déclaration","She signed her statement."],["📣","to charge somebody with","poursuivre quelqu'un pour","He was charged with fraud."],["💼","the right to a lawyer","le droit à un avocat","You have the right to a lawyer."],["🔑","to release","remettre en liberté","He was released without charge."],["🏠","a search warrant","un mandat de perquisition","The police need a search warrant."]]},{"endialog":{"situation":"Commissariat du 8e arrondissement. M. Traoré est entendu ; son avocat arrive.","lines":[["Officer","#1f5f8b","Mr. Traoré, you are being held in police custody for questioning.","Monsieur Traoré, vous êtes placé en garde à vue pour être entendu."],["Mr. Traoré","#b5651d","Why? What have I done?","Pourquoi ? Qu'est-ce que j'ai fait ?"],["Officer","#1f5f8b","You are suspected of breach of trust. You may remain silent, and you may ask for a lawyer.","Vous êtes soupçonné d'abus de confiance. Vous pouvez garder le silence et demander un avocat."],["Mr. Traoré","#b5651d","I want to call my lawyer, please.","Je veux appeler mon avocat, s'il vous plaît."],["Lawyer","#23468f","Good evening, officer. I'm Mr. Traoré's lawyer. I must speak with my client in private.","Bonsoir, monsieur l'officier. Je suis l'avocat de M. Traoré. Je dois m'entretenir en privé avec mon client."],["Officer","#1f5f8b","Of course. You have thirty minutes.","Bien sûr. Vous avez trente minutes."],["Lawyer","#23468f","Mr. Traoré, you don't have to answer questions you don't understand. Read your statement carefully before you sign it.","Monsieur Traoré, vous n'êtes pas obligé de répondre aux questions que vous ne comprenez pas. Lisez bien votre déposition avant de la signer."]]}},{"h":"Grammaire : les verbes modaux"},{"table":{"h":["Modal","Sens","Exemple"],"r":[["**must**","obligation forte","Witnesses **must** tell the truth."],["**must not**","interdiction","Officers **must not** use violence."],["**don't have to**","absence d'obligation","You **don't have to** answer."],["**may**","permission formelle","You **may** ask for a lawyer."],["**should**","conseil","You **should** read before signing."],["**shall**","obligation dans un texte juridique","The officer **shall** inform the prosecutor."]]}},{"box":"*Must not* (interdiction) et *don't have to* (absence d'obligation) ne se confondent pas : *You must not lie* (il est interdit de mentir) ; *You don't have to come* (tu n'es pas obligé de venir).","title":"Piège","kind":"piege"},{"box":"En Côte d'Ivoire, la durée de la garde à vue et les droits de la personne gardée à vue sont fixés par le Code de procédure pénale. Le dialogue est un exercice de langue, pas une consultation.","title":"Lien avec le droit ivoirien","kind":"marge"},{"h":"À toi de jouer"},{"p":"Complète avec *must*, *must not*, *may* ou *don't have to* : (1) Officers ___ beat a suspect. (2) A suspect ___ ask for a lawyer. (3) You ___ sign a statement you don't agree with. (4) The police ___ respect the law."},{"corrige":[{"p":"(1) must not ; (2) may ; (3) don't have to ; (4) must."}]}]},{"id":"lawfirm","title":"Unit 7 · At the law firm","body":[{"illus":"lawfirm","cap":"A first meeting with a client"},{"p":"Le premier rendez-vous avec un client : écouter les faits, poser des questions, donner un conseil. C'est le cas pratique, en anglais !"},{"envocab":[["🧑🏾‍💼","a client","un client","The client explains the facts."],["📑","a case","une affaire, un dossier","This is a difficult case."],["🧾","a claim","une demande, une réclamation","She filed a claim for damages."],["⚖","to sue","poursuivre en justice, assigner","He wants to sue his landlord."],["🏠","a landlord / a tenant","un bailleur / un locataire","The tenant owes three months' rent."],["💵","damages","des dommages-intérêts","You may claim damages."],["📜","to be entitled to","avoir droit à","You are entitled to compensation."],["⏳","a time limit","un délai","The time limit to appeal is short."]]},{"endialog":{"situation":"Cabinet de Maître Bamba, à Cocody. Mme Aka vient la consulter : son locataire ne paie plus son loyer.","lines":[["Maître Bamba","#23468f","Good morning, Mrs. Aka. Please have a seat. How can I help you?","Bonjour, madame Aka. Asseyez-vous, je vous en prie. Que puis-je faire pour vous ?"],["Mrs. Aka","#b5651d","My tenant hasn't paid his rent for four months.","Mon locataire n'a pas payé son loyer depuis quatre mois."],["Maître Bamba","#23468f","I see. Do you have a written lease?","Je vois. Avez-vous un bail écrit ?"],["Mrs. Aka","#b5651d","Yes, here it is. We signed it two years ago.","Oui, le voici. Nous l'avons signé il y a deux ans."],["Maître Bamba","#23468f","Did you send him a formal notice?","Lui avez-vous envoyé une mise en demeure ?"],["Mrs. Aka","#b5651d","No, I only called him. What can I do?","Non, je l'ai seulement appelé. Que puis-je faire ?"],["Maître Bamba","#23468f","First, we'll send a formal notice through a bailiff. If he still doesn't pay, you are entitled to sue him for the unpaid rent and ask for the termination of the lease.","D'abord, nous enverrons une mise en demeure par commissaire de justice. S'il ne paie toujours pas, vous pourrez l'assigner en paiement des loyers et demander la résiliation du bail."],["Mrs. Aka","#b5651d","Thank you, that's clear.","Merci, c'est clair."]]}},{"h":"Poser des questions et conseiller"},{"table":{"h":["Pour…","On dit…"],"r":[["demander les faits","*What happened? When did it happen? Do you have any documents?*"],["reformuler","*If I understand correctly, …*"],["conseiller","*I advise you to… / You should… / The best option is to…*"],["annoncer un droit","*You are entitled to… / You may…*"],["prévenir","*Be careful: the time limit is…*"]]}},{"box":"« En droit… En l'espèce… Par conséquent… » se dit aussi en anglais : *Under the law… In this case… Therefore…* Le raisonnement juridique est le même dans toutes les langues.","title":"Lien avec la méthodologie","kind":"cle"},{"h":"À toi de jouer"},{"p":"Par deux : un client dont la voiture a été endommagée par un taxi consulte un avocat. Le client explique les faits ; l'avocat pose trois questions et donne un conseil."},{"corrige":[{"quote":"*Client: A taxi hit my car yesterday at a red light. — Lawyer: Was anyone injured? Do you have photos? Did the police come? … I advise you to report the accident to your insurance company. You are entitled to compensation for the damage.*"}]}]},{"id":"contracts","title":"Unit 8 · Contracts","body":[{"illus":"contract","cap":"Offer + acceptance = agreement"},{"p":"Le contrat est partout : vente, bail, travail. On apprend son vocabulaire et la manière de lire une clause rédigée avec *shall*."},{"envocab":[["🤝","a contract / an agreement","un contrat","They signed a sales contract."],["👥","a party","une partie (au contrat)","Both parties agree."],["📣","an offer","une offre","He made an offer of 2 million CFA francs."],["✅","acceptance","l'acceptation","Acceptance must be clear."],["📑","a clause / a term","une clause","Read clause 5 carefully."],["❌","a breach of contract","une inexécution du contrat","Late delivery is a breach of contract."],["🗂","to terminate","résilier, résoudre","The buyer terminated the contract."],["✍️","to sign","signer","Sign here, please."]]},{"endialog":{"situation":"Au marché d'Adjamé, Koffi vend un ordinateur à Salimata ; ils rédigent un petit contrat.","lines":[["Salimata","#b5651d","I'd like to buy this laptop. What's your price?","J'aimerais acheter cet ordinateur. Quel est votre prix ?"],["Koffi","#0e6b4f","Two hundred thousand CFA francs.","Deux cent mille francs CFA."],["Salimata","#b5651d","I offer one hundred and eighty thousand.","Je propose cent quatre-vingt mille."],["Koffi","#0e6b4f","All right, I accept. I'll deliver it to your house within ten days.","D'accord, j'accepte. Je vous le livrerai chez vous sous dix jours."],["Salimata","#b5651d","Let's put it in writing. What happens if you deliver late?","Mettons-le par écrit. Que se passe-t-il si vous livrez en retard ?"],["Koffi","#0e6b4f","Then you may terminate the contract and get your money back.","Alors vous pourrez résilier le contrat et récupérer votre argent."],["Salimata","#b5651d","Perfect. Let's both sign.","Parfait. Signons tous les deux."]]}},{"h":"Lire une clause"},{"quote":"*Clause 3. The Seller **shall** deliver the laptop to the Buyer within ten (10) days of the signing of this agreement. If the Seller fails to deliver within that period, the Buyer **may** terminate the agreement and **shall be entitled to** a full refund.*"},{"table":{"h":["Mot","Sens dans la clause"],"r":[["**shall**","obligation : « le vendeur livrera » (doit livrer)"],["**within ten days of**","dans les dix jours à compter de"],["**fails to**","manque à, n'exécute pas"],["**may**","faculté : l'acheteur peut, s'il le souhaite"],["**shall be entitled to**","aura droit à"]]}},{"box":"Offre + acceptation = accord des volontés (*meeting of the minds*). C'est la formation du contrat vue en droit des obligations ; en droit ivoirien, l'article 1108 du Code civil exige le consentement, la capacité, un objet certain et une cause licite.","title":"Lien avec le droit civil","kind":"cle"},{"h":"À toi de jouer"},{"p":"Traduis en anglais juridique : « Le locataire paiera le loyer le premier jour de chaque mois. En cas de retard de plus de trente jours, le bailleur pourra résilier le bail. »"},{"corrige":[{"quote":"*The Tenant shall pay the rent on the first day of each month. If payment is more than thirty (30) days late, the Landlord may terminate the lease.*"}]}]},{"id":"persons","title":"Unit 9 · Persons and family","body":[{"illus":"persons","cap":"Legal personality, from birth to death"},{"p":"Le droit des personnes en anglais : naissance, état civil, capacité, absence. Les notions sont celles du cours de droit civil."},{"envocab":[["👪","legal personality","la personnalité juridique","Legal personality begins at birth."],["📄","a birth certificate","un acte de naissance","Bring your birth certificate."],["🧒🏾","a minor","un mineur","A minor cannot sign this contract alone."],["🛡","a guardian","un tuteur","The court appointed a guardian."],["🎂","the age of majority","l'âge de la majorité","The age of majority is eighteen."],["❓","a missing person","une personne absente ou disparue","Her husband is a missing person."],["📃","a declaration of death","un jugement déclaratif de décès","The court issued a declaration of death."],["🏠","domicile","le domicile","Your domicile is your main home."]]},{"endialog":{"situation":"Au cabinet, Mme Gnangbo explique que son mari ne donne plus de nouvelles depuis deux ans.","lines":[["Mrs. Gnangbo","#b5651d","My husband left two years ago and nobody has heard from him since.","Mon mari est parti il y a deux ans et personne n'a eu de ses nouvelles depuis."],["Lawyer","#23468f","Was he in any danger when he left? A shipwreck, a war, an accident?","Était-il en danger quand il est parti ? Un naufrage, une guerre, un accident ?"],["Mrs. Gnangbo","#b5651d","No. He just went to visit a friend in Mali.","Non. Il est simplement allé voir un ami au Mali."],["Lawyer","#23468f","Then, legally, he is an absent person, not a disappeared person. He is presumed to be alive.","Alors, juridiquement, il est absent, pas disparu. Il est présumé vivant."],["Mrs. Gnangbo","#b5651d","Can I remarry?","Puis-je me remarier ?"],["Lawyer","#23468f","Not yet. Your marriage is dissolved only when the declaration of absence becomes final. First, we must apply to the court.","Pas encore. Votre mariage n'est dissous que lorsque le jugement déclaratif d'absence est devenu définitif. Il faut d'abord saisir le tribunal."]]}},{"table":{"h":["Français","English"],"r":[["la capacité de jouissance / d'exercice","capacity to hold rights / capacity to exercise rights"],["l'émancipation","emancipation"],["la tutelle","guardianship"],["l'absence / la disparition","absence / disappearance"],["l'enfant conçu","the unborn child (*infans conceptus*)"]]}},{"h":"À toi de jouer"},{"p":"Réponds en anglais : (1) When does legal personality begin? (2) Can a minor sell his car alone? (3) Is an absent person presumed dead or alive?"},{"corrige":[{"ol":["It begins at birth, provided the child is born alive.","No, he can't. A minor lacks capacity to exercise his rights; his legal representative must act for him.","He is presumed to be alive."]}]}]},{"id":"falsefriends","title":"Unit 10 · False friends and legal Latin","body":[{"illus":"falsefriends","cap":"Actually ≠ actuellement"},{"p":"Les faux amis font dire le contraire de ce que l'on pense. Et le latin juridique, que l'on retrouve aussi en anglais, se prononce à l'anglaise."},{"table":{"h":["Mot anglais","Ne veut pas dire","Veut dire"],"r":[["**actually**","actuellement","en fait (actuellement = *currently*)"],["**eventually**","éventuellement","finalement (éventuellement = *possibly*)"],["**to attend**","attendre","assister à (attendre = *to wait*)"],["**a process**","un procès","un processus (un procès = *a trial*)"],["**jurisprudence**","la jurisprudence","la théorie du droit (la jurisprudence = *case law*)"],["**sensible**","sensible","raisonnable (sensible = *sensitive*)"],["**a magistrate**","un magistrat","un juge de rang inférieur, un juge de paix (un magistrat = *a judge, a prosecutor*)"],["**a library**","une librairie","une bibliothèque (une librairie = *a bookshop*)"]]}},{"endialog":{"situation":"Awa écrit un message à son professeur et fait relire son anglais par Moussa.","lines":[["Awa","#b5651d","Listen: « Actually, I am preparing my exam. Eventually, I will attend you after class. »","Écoute : « Actually, I am preparing my exam. Eventually, I will attend you after class. »"],["Moussa","#0e6b4f","Careful! « Actually » means « en fait ». You mean « currently ».","Attention ! « Actually » veut dire « en fait ». Tu veux dire « currently »."],["Awa","#b5651d","Oh! And « eventually »?","Oh ! Et « eventually » ?"],["Moussa","#0e6b4f","It means « finalement ». Say « possibly ». And « attend » means « assister à ». You want « wait for ».","Ça veut dire « finalement ». Dis « possibly ». Et « attend » veut dire « assister à ». Toi, tu veux « wait for »."],["Awa","#b5651d","So: « Currently, I am preparing my exam. Possibly, I will wait for you after class. »","Donc : « Currently, I am preparing my exam. Possibly, I will wait for you after class. »"],["Moussa","#0e6b4f","Perfect!","Parfait !"]]}},{"h":"Le latin juridique"},{"table":{"h":["Expression","Sens"],"r":[["*pacta sunt servanda*","les conventions doivent être respectées"],["*nemo auditur propriam turpitudinem allegans*","nul ne peut se prévaloir de sa propre turpitude"],["*infans conceptus pro nato habetur*","l'enfant conçu est tenu pour né (quand c'est son intérêt)"],["*res judicata*","l'autorité de la chose jugée"],["*bona fide*","de bonne foi"],["*prima facie*","à première vue"]]}},{"h":"À toi de jouer"},{"p":"Corrige ces phrases : (1) *I attended the bus for one hour.* (2) *Actually, the Court of Cassation has three chambers* (au sens de « en ce moment »). (3) *He was condemned in a long process.*"},{"corrige":[{"ol":["I waited for the bus for one hour.","Currently, the Court of Cassation has three chambers.","He was convicted after a long trial."]}]}]},{"id":"prononciation","title":"Unit 11 · Pronunciation lab","body":[{"illus":"pronunciation","cap":"Listen, repeat, record yourself"},{"p":"Le laboratoire de prononciation américaine. Dans la prononciation figurée, les MAJUSCULES marquent la syllabe accentuée. « â » se dit comme dans « pâte », « eu » est bref, « ii » et « ou » sont longs. Touche un mot pour l'entendre ; coche ceux que tu maîtrises."},{"rules":true},{"words":"jur"},{"words":"c21"},{"words":"pres"}]}];
M_EN.quiz = [{"q":"« I am a first-year law student » signifie…","a":["Je suis étudiant en première année de droit","Je suis le premier étudiant en droit","J'étudie le droit depuis un an","Je suis professeur de droit"],"c":0,"e":"*First-year* = de première année."},{"q":"Which branch deals with crimes and their punishment?","a":["Criminal law","Civil law","Administrative law","International law"],"c":0,"e":"Les litiges entre particuliers relèvent du *civil law*."},{"q":"« To settle a dispute » signifie…","a":["régler un litige","créer un litige","juger un crime","voter une loi"],"c":0,"e":"*A dispute* = un litige ; *to settle* = régler."},{"q":"Who represents society in criminal cases?","a":["The prosecutor","The lawyer","The clerk","The notary"],"c":0,"e":"Le procureur, magistrat du parquet."},{"q":"« Le greffier » en anglais :","a":["the court clerk","the bailiff","the notary","the attorney"],"c":0,"e":"*Bailiff* = commissaire de justice."},{"q":"Since 2020, the highest court for civil and criminal cases in Côte d'Ivoire is…","a":["the Court of Cassation","the Supreme Court","the Council of State","the Court of Auditors"],"c":0,"e":"La Cour suprême a été remplacée par trois hautes juridictions."},{"q":"Mets au passif : « The court quashed the judgment. »","a":["The judgment was quashed by the court.","The judgment is quashing by the court.","The court was quashed by the judgment.","The judgment quashed the court."],"c":0,"e":"*Be* conjugué + participe passé."},{"q":"« How do you plead? » demande au prévenu…","a":["s'il se reconnaît coupable ou non","son adresse","le nom de son avocat","s'il veut faire appel"],"c":0,"e":"Réponse : *guilty* ou *not guilty*."},{"q":"« Objection sustained » signifie…","a":["objection retenue","objection rejetée","objection reportée","objection interdite"],"c":0,"e":"*Overruled* = rejetée."},{"q":"Complète : « You ___ answer: you have the right to remain silent. »","a":["don't have to","must","must not","shall"],"c":0,"e":"Absence d'obligation."},{"q":"Complète : « Officers ___ use violence against a suspect. »","a":["must not","don't have to","may","should"],"c":0,"e":"Interdiction."},{"q":"« You are entitled to compensation » signifie…","a":["Vous avez droit à une indemnisation","Vous devez payer une indemnité","Vous êtes poursuivi","Vous êtes condamné"],"c":0,"e":"*To be entitled to* = avoir droit à."},{"q":"Dans un contrat, « The Seller shall deliver… » exprime…","a":["une obligation","une simple possibilité","un conseil","une interdiction"],"c":0,"e":"*Shall* = obligation dans les textes juridiques."},{"q":"« A breach of contract » est…","a":["une inexécution du contrat","une clause du contrat","la signature du contrat","une offre"],"c":0,"e":"*To breach* = violer, manquer à."},{"q":"« A minor » est…","a":["un mineur","un mineur de fond","un juge","un tuteur"],"c":0,"e":"*Guardian* = tuteur."},{"q":"« Actually » signifie…","a":["en fait","actuellement","éventuellement","réellement actuel"],"c":0,"e":"Actuellement = *currently*."},{"q":"Un procès se dit…","a":["a trial","a process","a court","a hearing"],"c":0,"e":"*A process* = un processus ; *a hearing* = une audience."},{"q":"La jurisprudence (décisions des tribunaux) se dit…","a":["case law","jurisprudence","legislation","doctrine"],"c":0,"e":"En anglais, *jurisprudence* désigne la théorie du droit."},{"q":"Où est l'accent tonique dans « lawyer » ?","a":["LAW-yer","law-YER","les deux syllabes","aucune"],"c":0,"e":"Accent sur la première syllabe : LÂ-yeur."}];
M_EN.cards = [["a law student","un étudiant en droit"],["a lecture","un cours magistral"],["a tutorial","des TD"],["criminal law","droit pénal"],["civil law","droit civil"],["to enforce","faire appliquer"],["to settle a dispute","régler un litige"],["a prosecutor","un procureur"],["a court clerk","un greffier"],["a bailiff","un commissaire de justice"],["a notary","un notaire"],["the Court of Cassation","la Cour de cassation"],["the Council of State","le Conseil d'État"],["to appeal","faire appel"],["jurisdiction","la compétence"],["a trial","un procès"],["a hearing","une audience"],["the defendant","le prévenu"],["a witness","un témoin"],["evidence","les preuves"],["guilty","coupable"],["to acquit","relaxer, acquitter"],["a sentence","une peine"],["a fine","une amende"],["police custody","la garde à vue"],["a statement","une déposition"],["a search warrant","un mandat de perquisition"],["to sue","assigner en justice"],["a landlord","un bailleur"],["a tenant","un locataire"],["to be entitled to","avoir droit à"],["a time limit","un délai"],["an offer","une offre"],["acceptance","l'acceptation"],["a breach of contract","une inexécution du contrat"],["shall","devra (obligation juridique)"],["a minor","un mineur"],["a guardian","un tuteur"],["a birth certificate","un acte de naissance"],["case law","la jurisprudence"],["actually","en fait"],["eventually","finalement"],["to attend","assister à"]];
const WORDS = {"jur": [{"word": "law", "ipa": "/lɑː/", "sens": "le droit ; une loi", "fig": "LÂ", "tip": "Un seul son long, comme dans « pâte ». Jamais « lo-ou ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/law"}, {"word": "lawyer", "ipa": "/ˈlɑː.jɚ/", "sens": "avocat", "fig": "LÂ-yeur", "tip": "Accent sur la 1re syllabe ; le r final se prononce.", "url": "https://dictionary.cambridge.org/us/dictionary/english/lawyer"}, {"word": "judge", "ipa": "/dʒʌdʒ/", "sens": "juge", "fig": "DJEUDJ", "tip": "« dj » au début et à la fin ; voyelle courte « eu ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/judge"}, {"word": "judgment", "ipa": "/ˈdʒʌdʒ.mənt/", "sens": "jugement", "fig": "DJEUDJ-meunt", "tip": "Le d ne s'entend pas séparément : « djeudj-meunt ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/judgment"}, {"word": "court", "ipa": "/kɔːrt/", "sens": "tribunal", "fig": "KORT", "tip": "Le r américain se prononce, langue recourbée.", "url": "https://dictionary.cambridge.org/us/dictionary/english/court"}, {"word": "contract", "ipa": "/ˈkɑːn.trækt/", "sens": "contrat", "fig": "KÂN-trakt", "tip": "Nom : accent au début. Verbe : con-TRACT.", "url": "https://dictionary.cambridge.org/us/dictionary/english/contract"}, {"word": "evidence", "ipa": "/ˈev.ə.dəns/", "sens": "preuve(s)", "fig": "È-veu-deuns", "tip": "Accent sur la 1re syllabe, pas sur « vi ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/evidence"}, {"word": "witness", "ipa": "/ˈwɪt.nəs/", "sens": "témoin", "fig": "OUÏT-neus", "tip": "Le w se dit « ou » ; i court.", "url": "https://dictionary.cambridge.org/us/dictionary/english/witness"}, {"word": "plaintiff", "ipa": "/ˈpleɪn.t̬ɪf/", "sens": "demandeur", "fig": "PLÉÏN-tif", "tip": "« ai » se dit « éï ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/plaintiff"}, {"word": "defendant", "ipa": "/dɪˈfen.dənt/", "sens": "défendeur, prévenu", "fig": "di-FÈN-deunt", "tip": "Accent sur la 2e syllabe.", "url": "https://dictionary.cambridge.org/us/dictionary/english/defendant"}, {"word": "prosecutor", "ipa": "/ˈprɑː.sə.kjuː.t̬ɚ/", "sens": "procureur", "fig": "PRÂ-seu-kiou-deur", "tip": "Accent au début ; le t entre voyelles devient un d léger.", "url": "https://dictionary.cambridge.org/us/dictionary/english/prosecutor"}, {"word": "appeal", "ipa": "/əˈpiːl/", "sens": "appel ; faire appel", "fig": "eu-PIIL", "tip": "« ea » = i long.", "url": "https://dictionary.cambridge.org/us/dictionary/english/appeal"}, {"word": "to sue", "ipa": "/suː/", "sens": "poursuivre en justice", "fig": "SOU", "tip": "Un seul son, « ou » long.", "url": "https://dictionary.cambridge.org/us/dictionary/english/sue"}, {"word": "clerk", "ipa": "/klɝːk/", "sens": "greffier", "fig": "KLEURK", "tip": "En américain « kleurk », pas « klark ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/clerk"}, {"word": "cassation", "ipa": "/kæˈseɪ.ʃən/", "sens": "cassation", "fig": "ka-SÉÏ-cheun", "tip": "« -tion » se dit toujours « cheun ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/cassation"}, {"word": "jurisprudence", "ipa": "/ˌdʒʊr.ɪsˈpruː.dəns/", "sens": "jurisprudence", "fig": "djour-is-PROU-deuns", "tip": "Accent sur « pru » ; « j » = « dj ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/jurisprudence"}, {"word": "constitution", "ipa": "/ˌkɑːn.stəˈtuː.ʃən/", "sens": "constitution", "fig": "kân-steu-TOU-cheun", "tip": "Accent sur « tu », prononcé « tou ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/constitution"}, {"word": "student", "ipa": "/ˈstuː.dənt/", "sens": "étudiant", "fig": "STOU-deunt", "tip": "En américain « stou », pas « stiou ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/student"}, {"word": "university", "ipa": "/ˌjuː.nəˈvɝː.sə.t̬i/", "sens": "université", "fig": "iou-neu-VEUR-seu-di", "tip": "Commence par « iou » ; t final ≈ d léger.", "url": "https://dictionary.cambridge.org/us/dictionary/english/university"}], "pres": [{"word": "field", "ipa": "/fiːld/", "sens": "domaine", "fig": "FIILD", "tip": "« ie » = i long.", "url": "https://dictionary.cambridge.org/us/dictionary/english/field"}, {"word": "opportunity", "ipa": "/ˌɑː.pɚˈtuː.nə.t̬i/", "sens": "occasion", "fig": "â-peur-TOU-neu-di", "tip": "Accent sur « tu ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/opportunity"}, {"word": "introduce", "ipa": "/ˌɪn.trəˈduːs/", "sens": "présenter", "fig": "in-treu-DOUS", "tip": "Accent sur la dernière syllabe.", "url": "https://dictionary.cambridge.org/us/dictionary/english/introduce"}, {"word": "myself", "ipa": "/maɪˈself/", "sens": "moi-même", "fig": "maï-SÈLF", "tip": "« my » = « maï ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/myself"}, {"word": "beautiful", "ipa": "/ˈbjuː.t̬ə.fəl/", "sens": "beau, belle", "fig": "BIOU-deu-feul", "tip": "t entre voyelles ≈ d léger.", "url": "https://dictionary.cambridge.org/us/dictionary/english/beautiful"}, {"word": "country", "ipa": "/ˈkʌn.tri/", "sens": "pays", "fig": "KEUN-tri", "tip": "« ou » se dit « eu » : jamais « kaoun-tri ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/country"}, {"word": "Africa", "ipa": "/ˈæf.rɪ.kə/", "sens": "Afrique", "fig": "A-fri-keu", "tip": "Accent sur la 1re syllabe.", "url": "https://dictionary.cambridge.org/us/dictionary/english/africa"}, {"word": "interest", "ipa": "/ˈɪn.trɪst/", "sens": "intérêt", "fig": "IN-trist", "tip": "Deux syllabes seulement.", "url": "https://dictionary.cambridge.org/us/dictionary/english/interest"}, {"word": "communication", "ipa": "/kəˌmjuː.nəˈkeɪ.ʃən/", "sens": "communication", "fig": "keu-miou-neu-KÉÏ-cheun", "tip": "Accent sur « ca ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/communication"}, {"word": "languages", "ipa": "/ˈlæŋ.ɡwɪdʒ.ɪz/", "sens": "langues", "fig": "LANG-gouï-djiz", "tip": "« gu » = « gou » ; finale « djiz ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/language"}, {"word": "cooperation", "ipa": "/koʊˌɑː.pəˈreɪ.ʃən/", "sens": "coopération", "fig": "kô-â-peu-RÉÏ-cheun", "tip": "Les deux o se prononcent séparément.", "url": "https://dictionary.cambridge.org/us/dictionary/english/cooperation"}, {"word": "motivated", "ipa": "/ˈmoʊ.t̬ə.veɪ.t̬ɪd/", "sens": "motivé", "fig": "MÔ-deu-véï-did", "tip": "-ed après t se dit « id ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/motivated"}, {"word": "ambitious", "ipa": "/æmˈbɪʃ.əs/", "sens": "ambitieux", "fig": "am-BI-cheus", "tip": "« -tious » = « cheus ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/ambitious"}, {"word": "hardworking", "ipa": "/ˌhɑːrdˈwɝː.kɪŋ/", "sens": "travailleur", "fig": "hard-OUEUR-king", "tip": "h soufflé ; « wor » = « oueur ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/hard-working"}, {"word": "knowledge", "ipa": "/ˈnɑː.lɪdʒ/", "sens": "connaissances", "fig": "NÂ-lidj", "tip": "Le k est muet.", "url": "https://dictionary.cambridge.org/us/dictionary/english/knowledge"}, {"word": "skills", "ipa": "/skɪlz/", "sens": "compétences", "fig": "SKILZ", "tip": "Le s final se dit « z ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/skill"}, {"word": "meaningful", "ipa": "/ˈmiː.nɪŋ.fəl/", "sens": "qui a du sens", "fig": "MII-ning-feul", "tip": "« ea » = i long.", "url": "https://dictionary.cambridge.org/us/dictionary/english/meaningful"}, {"word": "relationships", "ipa": "/rɪˈleɪ.ʃən.ʃɪps/", "sens": "relations", "fig": "ri-LÉÏ-cheun-chips", "tip": "Accent sur « la ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/relationship"}, {"word": "contribute", "ipa": "/kənˈtrɪb.juːt/", "sens": "contribuer", "fig": "keun-TRI-biout", "tip": "Accent sur la 2e syllabe.", "url": "https://dictionary.cambridge.org/us/dictionary/english/contribute"}, {"word": "community", "ipa": "/kəˈmjuː.nə.t̬i/", "sens": "communauté", "fig": "keu-MIOU-neu-di", "tip": "Accent sur « mu ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/community"}, {"word": "diversity", "ipa": "/dɪˈvɝː.sə.t̬i/", "sens": "diversité", "fig": "di-VEUR-seu-di", "tip": "Accent sur « ver ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/diversity"}, {"word": "education", "ipa": "/ˌedʒ.əˈkeɪ.ʃən/", "sens": "éducation", "fig": "è-djeu-KÉÏ-cheun", "tip": "« du » = « djeu ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/education"}, {"word": "teamwork", "ipa": "/ˈtiːm.wɝːk/", "sens": "travail d'équipe", "fig": "TIIM-oueurk", "tip": "Accent sur « team ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/teamwork"}, {"word": "respect", "ipa": "/rɪˈspekt/", "sens": "respect", "fig": "ri-SPÈKT", "tip": "Accent sur la 2e syllabe.", "url": "https://dictionary.cambridge.org/us/dictionary/english/respect"}, {"word": "attention", "ipa": "/əˈten.ʃən/", "sens": "attention", "fig": "eu-TÈN-cheun", "tip": "Accent sur « ten ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/attention"}, {"word": "pleasure", "ipa": "/ˈpleʒ.ɚ/", "sens": "plaisir", "fig": "PLÈ-jeur", "tip": "« s » = « j » de « jour ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/pleasure"}, {"word": "professional", "ipa": "/prəˈfeʃ.ən.əl/", "sens": "professionnel", "fig": "preu-FÈ-cheu-neul", "tip": "Accent sur « fes ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/professional"}], "text": [{"text": "Good morning, everyone.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Good+morning%2C+everyone."}, {"text": "First of all, I would like to thank you for giving me the opportunity to introduce myself.", "url": "https://translate.google.com/?sl=en&tl=fr&text=First+of+all%2C+I+would+like+to+thank+you+for+giving+me+the+opportunity+to+introduce+myself."}, {"text": "My name is YAO Abigail.", "url": "https://translate.google.com/?sl=en&tl=fr&text=My+name+is+YAO+Abigail."}, {"text": "I'm from Côte d'Ivoire, a beautiful country in West Africa.", "url": "https://translate.google.com/?sl=en&tl=fr&text=I%27m+from+C%C3%B4te+d%27Ivoire%2C+a+beautiful+country+in+West+Africa."}, {"text": "I am a professional in my field, and I have a strong interest in communication, languages and international cooperation.", "url": "https://translate.google.com/?sl=en&tl=fr&text=I+am+a+professional+in+my+field%2C+and+I+have+a+strong+interest+in+communication%2C+languages+and+international+cooperation."}, {"text": "I'm a motivated, ambitious and hardworking person who enjoys learning new skills.", "url": "https://translate.google.com/?sl=en&tl=fr&text=I%27m+a+motivated%2C+ambitious+and+hardworking+person+who+enjoys+learning+new+skills."}, {"text": "I believe in the importance of education, teamwork, respect and cultural diversity.", "url": "https://translate.google.com/?sl=en&tl=fr&text=I+believe+in+the+importance+of+education%2C+teamwork%2C+respect+and+cultural+diversity."}, {"text": "In my free time, I enjoy reading about new ideas.", "url": "https://translate.google.com/?sl=en&tl=fr&text=In+my+free+time%2C+I+enjoy+reading+about+new+ideas."}, {"text": "My goal is to keep improving my knowledge and skills, to build meaningful professional relationships and to contribute positively to my community.", "url": "https://translate.google.com/?sl=en&tl=fr&text=My+goal+is+to+keep+improving+my+knowledge+and+skills%2C+to+build+meaningful+professional+relationships+and+to+contribute+positively+to+my+community."}, {"text": "Thank you for your attention.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Thank+you+for+your+attention."}, {"text": "It is a pleasure to meet you all.", "url": "https://translate.google.com/?sl=en&tl=fr&text=It+is+a+pleasure+to+meet+you+all."}], "c21": [{"word": "trial", "ipa": "/ˈtraɪ.əl/", "sens": "procès", "fig": "TRAÏ-eul", "tip": "Deux syllabes : « traï » puis « eul ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/trial"}, {"word": "hearing", "ipa": "/ˈhɪr.ɪŋ/", "sens": "audience", "fig": "HIR-ing", "tip": "h soufflé ; « ea » = i court ici.", "url": "https://dictionary.cambridge.org/us/dictionary/english/hearing"}, {"word": "case", "ipa": "/keɪs/", "sens": "affaire", "fig": "KÉÏS", "tip": "« a » = « éï ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/case"}, {"word": "ruling", "ipa": "/ˈruː.lɪŋ/", "sens": "décision", "fig": "ROU-ling", "tip": "« u » long = « ou ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/ruling"}, {"word": "sentence", "ipa": "/ˈsen.təns/", "sens": "peine ; phrase", "fig": "SÈN-teuns", "tip": "Accent sur la 1re syllabe.", "url": "https://dictionary.cambridge.org/us/dictionary/english/sentence"}, {"word": "fine", "ipa": "/faɪn/", "sens": "amende", "fig": "FAÏN", "tip": "« i » = « aï ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/fine"}, {"word": "damages", "ipa": "/ˈdæm.ɪ.dʒɪz/", "sens": "dommages-intérêts", "fig": "DA-mi-djiz", "tip": "« -ges » = « djiz ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/damages"}, {"word": "guilty", "ipa": "/ˈɡɪl.ti/", "sens": "coupable", "fig": "GUIL-ti", "tip": "Le u est muet : « guil ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/guilty"}, {"word": "to acquit", "ipa": "/əˈkwɪt/", "sens": "acquitter", "fig": "eu-KOUIT", "tip": "Accent sur la 2e syllabe.", "url": "https://dictionary.cambridge.org/us/dictionary/english/acquit"}, {"word": "to charge", "ipa": "/tʃɑːrdʒ/", "sens": "inculper", "fig": "TCHÂRDJ", "tip": "« ch » = « tch » ; r prononcé.", "url": "https://dictionary.cambridge.org/us/dictionary/english/charge"}, {"word": "attorney", "ipa": "/əˈtɝː.ni/", "sens": "avocat (US)", "fig": "eu-TEUR-ni", "tip": "Accent sur « tor » = « teur ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/attorney"}, {"word": "barrister", "ipa": "/ˈber.ɪ.stɚ/", "sens": "avocat plaidant (UK)", "fig": "BÈ-ris-teur", "tip": "Accent sur la 1re syllabe.", "url": "https://dictionary.cambridge.org/us/dictionary/english/barrister"}, {"word": "solicitor", "ipa": "/səˈlɪs.ɪ.t̬ɚ/", "sens": "avocat-conseil (UK)", "fig": "seu-LI-si-deur", "tip": "Accent sur « li ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/solicitor"}, {"word": "bailiff", "ipa": "/ˈbeɪ.lɪf/", "sens": "commissaire de justice", "fig": "BÉÏ-lif", "tip": "« ai » = « éï ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/bailiff"}, {"word": "notary", "ipa": "/ˈnoʊ.t̬ɚ.i/", "sens": "notaire", "fig": "NÔ-deu-ri", "tip": "t entre voyelles ≈ d léger.", "url": "https://dictionary.cambridge.org/us/dictionary/english/notary"}, {"word": "magistrate", "ipa": "/ˈmædʒ.ə.streɪt/", "sens": "juge de rang inférieur", "fig": "MA-djeu-stréït", "tip": "Accent sur la 1re syllabe.", "url": "https://dictionary.cambridge.org/us/dictionary/english/magistrate"}, {"word": "criminal", "ipa": "/ˈkrɪm.ə.nəl/", "sens": "pénal ; criminel", "fig": "KRI-meu-neul", "tip": "Accent sur la 1re syllabe.", "url": "https://dictionary.cambridge.org/us/dictionary/english/criminal"}, {"word": "civil", "ipa": "/ˈsɪv.əl/", "sens": "civil", "fig": "SI-veul", "tip": "Accent sur la 1re syllabe.", "url": "https://dictionary.cambridge.org/us/dictionary/english/civil"}, {"word": "administrative", "ipa": "/ədˈmɪn.ə.streɪ.t̬ɪv/", "sens": "administratif", "fig": "eud-MI-neu-stréï-div", "tip": "Accent sur « min ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/administrative"}, {"word": "council", "ipa": "/ˈkaʊn.səl/", "sens": "conseil", "fig": "KAOUN-seul", "tip": "« ou » = « aou ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/council"}, {"word": "auditor", "ipa": "/ˈɑː.dɪ.t̬ɚ/", "sens": "contrôleur des comptes", "fig": "Â-di-deur", "tip": "« au » = « â ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/auditor"}, {"word": "society", "ipa": "/səˈsaɪ.ə.t̬i/", "sens": "société", "fig": "seu-SAÏ-eu-di", "tip": "Accent sur « ci » = « saï ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/society"}, {"word": "dispute", "ipa": "/dɪˈspjuːt/", "sens": "litige", "fig": "di-SPIOUT", "tip": "Accent sur la 2e syllabe.", "url": "https://dictionary.cambridge.org/us/dictionary/english/dispute"}, {"word": "labor", "ipa": "/ˈleɪ.bɚ/", "sens": "travail", "fig": "LÉÏ-beur", "tip": "Orthographe US : labor ; UK : labour.", "url": "https://dictionary.cambridge.org/us/dictionary/english/labor"}, {"word": "actually", "ipa": "/ˈæk.tʃu.ə.li/", "sens": "en fait", "fig": "AK-tchou-eu-li", "tip": "Faux ami : ne veut pas dire « actuellement ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/actually"}, {"word": "eventually", "ipa": "/ɪˈven.tʃu.ə.li/", "sens": "finalement", "fig": "i-VÈN-tchou-eu-li", "tip": "Faux ami : ne veut pas dire « éventuellement ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/eventually"}, {"word": "to attend", "ipa": "/əˈtend/", "sens": "assister à", "fig": "eu-TÈND", "tip": "Faux ami : ne veut pas dire « attendre ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/attend"}, {"word": "process", "ipa": "/ˈprɑː.ses/", "sens": "processus", "fig": "PRÂ-sès", "tip": "Faux ami : un procès = a trial.", "url": "https://dictionary.cambridge.org/us/dictionary/english/process"}, {"word": "must", "ipa": "/mʌst/", "sens": "devoir (obligation)", "fig": "MEUST", "tip": "u = « eu » bref.", "url": "https://dictionary.cambridge.org/us/dictionary/english/must"}, {"word": "shall", "ipa": "/ʃæl/", "sens": "devra (texte juridique)", "fig": "CHAL", "tip": "« sh » = « ch ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/shall"}], "read": [{"text": "Côte d'Ivoire has a civil law system inherited from France.", "url": "https://translate.google.com/?sl=en&tl=fr&text=C%C3%B4te+d%27Ivoire+has+a+civil+law+system+inherited+from+France."}, {"text": "Its laws are mainly written down and collected in codes, such as the Civil Code and the Criminal Code.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Its+laws+are+mainly+written+down+and+collected+in+codes%2C+such+as+the+Civil+Code+and+the+Criminal+Code."}, {"text": "Judges apply these written rules to the cases they hear.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Judges+apply+these+written+rules+to+the+cases+they+hear."}, {"text": "Since the constitutional reform of 2020, the Supreme Court no longer exists.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Since+the+constitutional+reform+of+2020%2C+the+Supreme+Court+no+longer+exists."}, {"text": "Three high courts now stand at the top of the system: the Court of Cassation, for civil, commercial and criminal cases; the Council of State, for administrative cases; and the Court of Auditors, which controls public finances.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Three+high+courts+now+stand+at+the+top+of+the+system%3A+the+Court+of+Cassation%2C+for+civil%2C+commercial+and+criminal+cases%3B+the+Council+of+State%2C+for+administrative+cases%3B+and+the+Court+of+Auditors%2C+which+controls+public+finances."}, {"text": "The Constitutional Council is separate: it checks that laws respect the Constitution and settles disputes about national elections.", "url": "https://translate.google.com/?sl=en&tl=fr&text=The+Constitutional+Council+is+separate%3A+it+checks+that+laws+respect+the+Constitution+and+settles+disputes+about+national+elections."}, {"text": "Most cases begin in a court of first instance.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Most+cases+begin+in+a+court+of+first+instance."}, {"text": "A party who loses can appeal to a court of appeal, which hears the case again.", "url": "https://translate.google.com/?sl=en&tl=fr&text=A+party+who+loses+can+appeal+to+a+court+of+appeal%2C+which+hears+the+case+again."}, {"text": "Finally, a party may bring the case before the Court of Cassation, which only checks whether the law was correctly applied.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Finally%2C+a+party+may+bring+the+case+before+the+Court+of+Cassation%2C+which+only+checks+whether+the+law+was+correctly+applied."}, {"text": "Many people work in the courts.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Many+people+work+in+the+courts."}, {"text": "Judges decide cases, while prosecutors represent society and bring criminal charges.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Judges+decide+cases%2C+while+prosecutors+represent+society+and+bring+criminal+charges."}, {"text": "Lawyers advise and defend their clients, and court clerks keep the records of the court.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Lawyers+advise+and+defend+their+clients%2C+and+court+clerks+keep+the+records+of+the+court."}, {"text": "Abidjan is also the seat of the Common Court of Justice and Arbitration (CCJA) of OHADA, an organisation that harmonises business law in seventeen African countries.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Abidjan+is+also+the+seat+of+the+Common+Court+of+Justice+and+Arbitration+%28CCJA%29+of+OHADA%2C+an+organisation+that+harmonises+business+law+in+seventeen+African+countries."}], "law": [{"word": "regulation", "ipa": "/ˌreɡ.jəˈleɪ.ʃən/", "sens": "règlement, réglementation", "fig": "rè-guieu-LÉÏ-cheun", "tip": "Accent sur « la » ; « -tion » = « cheun ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/regulation"}, {"word": "to enforce", "ipa": "/ɪnˈfɔːrs/", "sens": "faire appliquer", "fig": "in-FORS", "tip": "Accent sur la 2e syllabe ; r prononcé.", "url": "https://dictionary.cambridge.org/us/dictionary/english/enforce"}, {"word": "enforcement", "ipa": "/ɪnˈfɔːrs.mənt/", "sens": "application (de la loi)", "fig": "in-FORS-meunt", "tip": "Accent sur « for ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/enforcement"}, {"word": "authority", "ipa": "/əˈθɔːr.ə.t̬i/", "sens": "autorité", "fig": "eu-THO-reu-di", "tip": "« th » soufflé, langue entre les dents.", "url": "https://dictionary.cambridge.org/us/dictionary/english/authority"}, {"word": "legitimate", "ipa": "/ləˈdʒɪt̬.ə.mət/", "sens": "légitime", "fig": "leu-DJI-deu-meut", "tip": "Accent sur « gi » = « dji ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/legitimate"}, {"word": "behavior", "ipa": "/bɪˈheɪ.vjɚ/", "sens": "comportement", "fig": "bi-HÉÏ-vieur", "tip": "Orthographe US : behavior ; UK : behaviour.", "url": "https://dictionary.cambridge.org/us/dictionary/english/behavior"}, {"word": "fairness", "ipa": "/ˈfer.nəs/", "sens": "équité", "fig": "FÈR-neus", "tip": "« air » = « èr ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/fairness"}, {"word": "penalty", "ipa": "/ˈpen.əl.ti/", "sens": "sanction, peine", "fig": "PÈ-neul-ti", "tip": "Accent sur la 1re syllabe.", "url": "https://dictionary.cambridge.org/us/dictionary/english/penalty"}, {"word": "punishment", "ipa": "/ˈpʌn.ɪʃ.mənt/", "sens": "punition, peine", "fig": "PEU-nich-meunt", "tip": "« u » = « eu » bref.", "url": "https://dictionary.cambridge.org/us/dictionary/english/punishment"}, {"word": "equality", "ipa": "/iˈkwɑː.lə.t̬i/", "sens": "égalité", "fig": "i-KOUÂ-leu-di", "tip": "Accent sur « qua ».", "url": "https://dictionary.cambridge.org/us/dictionary/english/equality"}, {"word": "to govern", "ipa": "/ˈɡʌv.ɚn/", "sens": "régir, gouverner", "fig": "GUEU-veurn", "tip": "« o » = « eu » bref.", "url": "https://dictionary.cambridge.org/us/dictionary/english/govern"}], "lawtext": [{"text": "Law is a system of rules and regulations established and enforced by the State or other legitimate authorities to regulate human behavior, maintain order in society, protect individual rights and ensure justice.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Law+is+a+system+of+rules+and+regulations+established+and+enforced+by+the+State+or+other+legitimate+authorities+to+regulate+human+behavior%2C+maintain+order+in+society%2C+protect+individual+rights+and+ensure+justice.", "qsize": 110}, {"text": "In simple words, law is a set of rules that people must obey in a society.", "url": "https://translate.google.com/?sl=en&tl=fr&text=In+simple+words%2C+law+is+a+set+of+rules+that+people+must+obey+in+a+society.", "qsize": 90}, {"text": "These rules help maintain peace, protect people's rights and punish those who break them.", "url": "https://translate.google.com/?sl=en&tl=fr&text=These+rules+help+maintain+peace%2C+protect+people%27s+rights+and+punish+those+who+break+them.", "qsize": 90}, {"text": "Law consists of rules that regulate human conduct.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Law+consists+of+rules+that+regulate+human+conduct.", "qsize": 90}, {"text": "Laws are established or recognized by legitimate authorities.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Laws+are+established+or+recognized+by+legitimate+authorities.", "qsize": 90}, {"text": "Laws can be enforced by courts and other competent institutions.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Laws+can+be+enforced+by+courts+and+other+competent+institutions.", "qsize": 90}, {"text": "Law aims to protect rights and promote fairness.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Law+aims+to+protect+rights+and+promote+fairness.", "qsize": 90}, {"text": "Breaking the law may result in penalties or other legal consequences.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Breaking+the+law+may+result+in+penalties+or+other+legal+consequences.", "qsize": 90}, {"text": "Criminal law deals with crimes and their punishment.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Criminal+law+deals+with+crimes+and+their+punishment.", "qsize": 90}, {"text": "Civil law deals with disputes between individuals or organizations.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Civil+law+deals+with+disputes+between+individuals+or+organizations.", "qsize": 90}, {"text": "Constitutional law governs the structure and powers of the State.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Constitutional+law+governs+the+structure+and+powers+of+the+State.", "qsize": 90}, {"text": "Administrative law regulates the activities of government authorities.", "url": "https://translate.google.com/?sl=en&tl=fr&text=Administrative+law+regulates+the+activities+of+government+authorities.", "qsize": 90}, {"text": "International law governs relations between States and other international actors.", "url": "https://translate.google.com/?sl=en&tl=fr&text=International+law+governs+relations+between+States+and+other+international+actors.", "qsize": 90}]};

// ===== Exercices d'application de fin de leçon (corrigés à déplier), schémas et compléments d'évaluation
(function () {
  const S = { intro: M_INTRO, dc: M_DC, dm: M_DM, oj: M_OJ, metho: M_METHO, info: M_INFO, tee: M_TEE, en: M_EN };
  const les = k => { const [s, l] = k.split("/"); return S[s].lessons.find(x => x.id === l); };
  const txt = b => [b.h, b.p, b.box, b.title].filter(Boolean).join(" ");
  const ILL = [["intro/loi","droit/kelsen","La hiérarchie des normes (pyramide de Kelsen)",{"after":"La hiérarchie des normes"}],["intro/patrimoniaux","droit/droits","La classification des droits subjectifs",{"after":"Deuxième partie, chapitre premier"}],["oj/introduction","droit/juridictions","Les juridictions ivoiriennes depuis 2020",{"before":"III. Les sources"}],["oj/exception2","droit/penal","Les étapes du procès pénal",{"before":"Vocabulaire"}],["dc/fin","droit/absence","Les trois étapes de l'absence",{"before":"La fin de l'absence"}],["dm/synthese","droit/sources-dm","La hiérarchie des sources du droit musulman",{"after":"Le droit musulman s'organise"}],["metho/methode","droit/dissertation","Le plan d'une dissertation juridique",{}],["info/composants","droit/vonneumann","L'architecture de von Neumann",{"after":"Architecture"}]];
  for (const [k, illus, cap, w] of ILL) { const L = les(k); if (!L) continue; const fig = { illus, cap };
    const m = w.after || w.before, i = m ? L.body.findIndex(b => txt(b).includes(m)) : -1;
    if (i < 0) L.body.push(fig); else L.body.splice(w.after ? i + 1 : i, 0, fig); }
  const X = {"intro/introgen":[{"h":"Exercice d'application"},{"p":"Koffi affirme : « Le droit dit que le propriétaire peut user de sa chose ; j'ai donc le droit de vivre dans ma maison. » Dans cette phrase, distingue le droit objectif et le droit subjectif."},{"corrige":[{"p":"« Le propriétaire peut user de sa chose » est une **règle générale** qui vise tous les propriétaires : c'est le **droit objectif**."},{"p":"« J'ai le droit de vivre dans ma maison » est la **prérogative** que cette règle reconnaît à Koffi, personne déterminée : c'est un **droit subjectif**, ici son droit de propriété. Le droit objectif crée et protège le droit subjectif."}]}],"intro/caracteres":[{"h":"Exercice d'application"},{"p":"Un arrêté nomme M. Yao directeur d'un lycée. Un autre texte décide que « tout conducteur de moto doit porter un casque ». Lequel est une règle de droit ? Pourquoi ?"},{"corrige":[{"p":"Seul le second texte est une **règle de droit** : il est **général et impersonnel** (il vise tout conducteur de moto), **permanent** (il s'applique à chaque trajet jusqu'à son abrogation) et **obligatoire** (une amende sanctionne son non-respect)."},{"p":"L'arrêté qui nomme M. Yao est une **décision individuelle** : il vise une personne nommément désignée et s'épuise en une seule application."}]}],"intro/matieres":[{"h":"Exercice d'application"},{"p":"Classe chacun de ces litiges dans sa branche du droit : (1) un salarié conteste son licenciement ; (2) un commerçant ne paie pas son fournisseur ; (3) une Ivoirienne épouse un Malien à Paris et l'on se demande quelle loi régit le mariage ; (4) un citoyen conteste un arrêté du préfet."},{"corrige":[{"p":"(1) **Droit social** (droit du travail), droit mixte. (2) **Droit commercial** (droit des affaires, OHADA), droit privé. (3) **Droit international privé** : élément d'extranéité, conflit de lois ; c'est une branche du droit interne. (4) **Droit administratif**, droit public : action de l'Administration et rapports avec les administrés."}]}],"intro/loi":[{"h":"Exercice d'application"},{"p":"Un décret fixe l'âge minimum du mariage. Un étudiant soutient qu'il est irrégulier. A-t-il raison ?"},{"corrige":[{"p":"**Règle** : selon l'article 101 de la Constitution, la loi fixe les règles concernant **l'état et la capacité des personnes** ; ce qui ne relève pas de cette liste a un caractère réglementaire (article 103)."},{"p":"**Application** : l'âge du mariage touche à l'état et à la capacité des personnes ; il relève donc du **domaine de la loi**, votée par le Parlement."},{"p":"**Solution** : l'étudiant a raison ; un décret ne peut pas fixer cette règle. Il est contraire à une norme supérieure (pyramide de Kelsen) et peut être annulé par le juge administratif."}]}],"intro/forceloi":[{"h":"Exercice d'application"},{"p":"Un contrat de travail prévoit un salaire inférieur au salaire minimum. Un contrat de vente ne dit rien du lieu de paiement du prix. Quelle loi s'applique dans chaque cas ?"},{"corrige":[{"p":"Le **salaire minimum** est fixé par une **loi impérative**, d'ordre public : la clause contraire est **nulle** et le salarié a droit au salaire minimum."},{"p":"Le **lieu de paiement** est fixé par une **loi supplétive** : les parties pouvaient y déroger ; comme elles n'ont rien prévu, la loi supplétive **s'impose à elles**. Une loi supplétive n'est pas facultative."}]}],"intro/coutume":[{"h":"Exercice d'application"},{"p":"Dans un marché, les commerçants accordent depuis toujours un délai de huit jours pour payer, et chacun s'estime tenu de le respecter. Un autre usage veut qu'on offre un pagne à la naissance d'un enfant. Lequel est une coutume au sens juridique ?"},{"corrige":[{"p":"La coutume réunit un **élément matériel** (un usage ancien, constant, général, notoire) et un **élément psychologique** (la conviction qu'il est obligatoire, *opinio necessitatis*)."},{"p":"Le délai de paiement réunit les deux éléments : c'est une **coutume**, ici *praeter legem* (à côté de la loi), fréquente en droit des affaires. Le pagne offert à une naissance n'est qu'une **habitude** de politesse : personne ne s'estime juridiquement obligé."}]}],"intro/jurisprudence":[{"h":"Exercice d'application"},{"p":"Un texte de 1960 parle de « correspondance par lettre ». Un juge de 2026 doit décider s'il s'applique aux messages WhatsApp. Quelle méthode d'interprétation lui permet de répondre oui ?"},{"corrige":[{"p":"La **méthode exégétique** chercherait la volonté du législateur de 1960, qui ne connaissait pas WhatsApp : elle conduirait plutôt à refuser."},{"p":"La **méthode historique ou évolutive** (Saleilles) détache la loi de la volonté de son auteur pour l'adapter aux besoins de l'époque ; la **méthode téléologique** recherche le but du texte (protéger le secret des échanges). L'une et l'autre permettent d'appliquer le texte aux messages WhatsApp."}]}],"intro/interpretation":[{"h":"Exercice d'application"},{"p":"Une loi dispose : « Les mineurs ne peuvent pas acheter d'alcool. » Que peut-on en déduire pour les majeurs ? Quel raisonnement utilises-tu ?"},{"corrige":[{"p":"C'est un raisonnement **a contrario** : si la loi pose une règle pour un cas (les mineurs), la règle inverse vaut pour le cas contraire. Les **majeurs** peuvent donc acheter de l'alcool, sous réserve des autres règles."},{"p":"Attention : ce raisonnement ne vaut pas si la loi n'est qu'une illustration ; et la loi pénale, elle, est d'**interprétation stricte**."}]}],"intro/espace":[{"h":"Exercice d'application"},{"p":"Un touriste français vole un téléphone à Abidjan. Un Ivoirien de 17 ans veut se marier en France. Quelle loi s'applique dans chaque cas ?"},{"corrige":[{"p":"**Le vol** : la loi pénale obéit au principe de **territorialité** ; elle s'applique à toutes les personnes présentes sur le territoire. Le touriste est jugé selon le **Code pénal ivoirien**."},{"p":"**La capacité de se marier** relève du **statut personnel** : la loi suit la personne (principe de **personnalité**). La capacité de l'Ivoirien reste régie par la **loi ivoirienne**, même en France."}]}],"intro/temps":[{"h":"Exercice d'application"},{"p":"Une loi nouvelle réduit la peine d'un délit de cinq à deux ans. Awa a commis ce délit avant la loi et n'est pas encore jugée. Par ailleurs, une autre loi nouvelle modifie les règles d'un contrat de bail signé il y a un an. Quelles lois appliquer ?"},{"corrige":[{"p":"**Pour Awa** : la loi pénale **plus douce** est **rétroactive** (*in mitius*) ; elle s'applique aux faits commis avant son entrée en vigueur et non encore définitivement jugés. Awa encourt **deux ans**."},{"p":"**Pour le bail** : les contrats en cours restent régis par la loi du jour de leur conclusion (**survie de la loi ancienne**), sauf si la loi nouvelle est d'ordre public impérieux."}]}],"intro/institution":[{"h":"Exercice d'application"},{"p":"Le tribunal de première instance a condamné Bakary à payer 2 millions FCFA. Il estime que le juge s'est trompé sur les faits. Que peut-il faire, devant quelle juridiction ?"},{"corrige":[{"p":"Grâce au principe du **double degré de juridiction**, Bakary peut faire **appel** devant la **cour d'appel**, qui rejuge l'affaire **en fait et en droit**."},{"p":"Il ne peut pas saisir directement la Cour de cassation : elle est **juge du droit** et ne réexamine pas les faits."}]}],"intro/patrimoniaux":[{"h":"Exercice d'application"},{"p":"Aminata est usufruitière d'une maison dont son fils est nu-propriétaire. Elle veut louer la maison et, plus tard, la vendre. Le peut-elle ?"},{"corrige":[{"p":"L'**usufruit** donne l'**usus** (habiter) et le **fructus** (percevoir les fruits, donc les loyers) ; le **nu-propriétaire** garde l'**abusus** (disposer)."},{"p":"Aminata peut donc **louer** la maison et encaisser les loyers. Elle ne peut **pas la vendre** seule : la vente relève de l'abusus, qui appartient à son fils."}]}],"intro/extrapatrimoniaux":[{"h":"Exercice d'application"},{"p":"Un magazine publie sans autorisation la photo d'un étudiant pour une publicité. L'étudiant peut-il vendre ce droit ? Que peut-il obtenir ?"},{"corrige":[{"p":"Le **droit à l'image** est un droit **extrapatrimonial** : attaché à la personne, il n'est pas évaluable en argent, il est **incessible** et intransmissible."},{"p":"Sa violation ouvre pourtant droit à **réparation** : l'étudiant peut obtenir des **dommages-intérêts** et l'arrêt de la publication. (Il peut autoriser une utilisation de son image, mais il ne cède pas le droit lui-même.)"}]}],"intro/chargepreuve":[{"h":"Exercice d'application"},{"p":"Koffi réclame à Yao 300 000 FCFA qu'il dit lui avoir prêtés. Yao répond qu'il a déjà remboursé. Qui doit prouver quoi ?"},{"corrige":[{"p":"**Règle** : « celui qui réclame l'exécution d'une obligation doit la prouver ; celui qui se prétend libéré doit justifier le paiement » (article 1315 du Code civil) : *actori incumbit probatio*."},{"p":"**Application** : Koffi doit d'abord prouver le **prêt**. S'il y parvient, la charge de la preuve se déplace : Yao doit prouver le **remboursement**."}]}],"intro/procedes":[{"h":"Exercice d'application"},{"p":"Un accident de la circulation et un contrat de vente d'une voiture à 5 millions FCFA : comment prouver chacun ?"},{"corrige":[{"p":"L'**accident** est un **fait juridique** : sa preuve est **libre** (témoins, constat, photos, expertise)."},{"p":"La **vente** est un **acte juridique** d'un montant élevé : elle se prouve en principe **par écrit** (acte sous seing privé ou acte authentique), et l'on ne peut prouver par témoins contre un écrit (article 1341 du Code civil), sauf exceptions (commencement de preuve par écrit, impossibilité, matière commerciale)."}]}],"intro/action":[{"h":"Exercice d'application"},{"p":"Un voisin agit en justice pour faire annuler un contrat signé entre deux autres personnes, qui ne le concerne pas. Un mineur de 15 ans assigne seul son débiteur. Ces actions sont-elles recevables ?"},{"corrige":[{"p":"**Le voisin** n'a pas d'**intérêt** direct et personnel : son action est **irrecevable** (« pas d'intérêt, pas d'action »)."},{"p":"**Le mineur** n'a pas la **capacité** d'agir seul : il doit agir par son **représentant légal**. Son action, exercée seul, est **irrecevable**."}]}],"intro/instance":[{"h":"Exercice d'application"},{"p":"Le tribunal a débouté Awa de sa demande contre Koffi, en remboursement d'un prêt. Un an plus tard, elle l'assigne de nouveau pour la même somme et le même prêt. Que décidera le juge ?"},{"corrige":[{"p":"**Règle** : l'**autorité de la chose jugée** interdit de rejuger un litige déjà tranché, s'il y a **triple identité** : mêmes parties, même objet, même cause (article 1351 du Code civil)."},{"p":"**Application** : mêmes parties (Awa et Koffi), même objet (la somme), même cause (le prêt)."},{"p":"**Solution** : la nouvelle demande est **irrecevable**. Awa aurait dû faire **appel** du premier jugement."}]}],"dc/intro":[{"h":"Exercice d'application"},{"p":"Classe ces matières : le mariage ; les impôts ; le contrat de vente ; l'organisation du Parlement ; la succession."},{"corrige":[{"p":"**Droit privé, droit civil** : le mariage et la succession (les personnes et la famille), le contrat de vente (les principaux contrats)."},{"p":"**Droit public** : les impôts (finances publiques) et l'organisation du Parlement (droit constitutionnel)."}]}],"dc/naissance":[{"h":"Exercice d'application"},{"p":"Moussa meurt le 1er décembre 2025. Son fils Ibrahim naît vivant le 15 juin 2026. Ibrahim peut-il hériter de son père ?"},{"corrige":[{"p":"**Règle** : la personnalité commence à la naissance, mais l'**enfant conçu** est considéré comme né chaque fois qu'il y va de son intérêt (*infans conceptus*), s'il **naît vivant**. La loi présume qu'il a été conçu entre le **300e** et le **180e jour** avant sa naissance."},{"p":"**Application** : le 300e jour avant le 15 juin 2026 est le 19 août 2025 ; le 180e jour est le 17 décembre 2025. Le décès du père (1er décembre 2025) se situe dans cette période : Ibrahim était **conçu** au jour du décès. Il a intérêt à hériter et il est né vivant."},{"p":"**Solution** : Ibrahim **hérite** de son père."}]}],"dc/fin":[{"h":"Exercice d'application"},{"p":"Yao a quitté son domicile en mars 2023 et ne donne plus aucune nouvelle, sans qu'aucun danger particulier soit connu. Sa femme veut se remarier. Que doit-elle faire, et quand la succession pourra-t-elle s'ouvrir ?"},{"corrige":[{"p":"**Qualification** : aucune circonstance dangereuse : c'est une **absence** (article 1er de la loi n° 2022-885), non une disparition."},{"p":"**Étapes** : après **1 an** sans nouvelles (mars 2024), elle saisit le tribunal, qui rend un jugement de **présomption d'absence** et nomme un administrateur ; après **2 ans** d'enquête, le tribunal rend le **jugement déclaratif d'absence**. Dès qu'il est définitif, le **mariage est dissous** : elle peut se remarier."},{"p":"**Succession** : elle s'ouvre avec le **jugement déclaratif de décès**, demandé **7 ans** après le jugement d'absence ou **10 ans** après les dernières nouvelles (mars 2033)."}]}],"dc/disparition":[{"h":"Exercice d'application"},{"p":"Un bateau de pêche ivoirien coule en haute mer lors d'une tempête ; deux marins ne sont pas retrouvés. Est-ce une absence ou une disparition ? Quel tribunal saisir ?"},{"corrige":[{"p":"**Qualification** : les marins ont cessé de paraître à la suite de **circonstances de nature à mettre leur vie en danger**, et leurs corps n'ont pas été retrouvés : c'est une **disparition** (article 13 de la loi n° 2022-885)."},{"p":"**Tribunal** : pour une disparition à bord d'un navire hors de Côte d'Ivoire, le tribunal du **port d'attache** du navire (article 15). La requête peut être **collective**. Le tribunal ordonne une enquête puis **déclare le décès** : le jugement tient lieu d'acte de décès."}]}],"dc/patrimoniaux":[{"h":"Exercice d'application"},{"p":"Classe ces biens : un champ de cacao ; le tracteur affecté à son exploitation par le propriétaire du champ ; une voiture ; des actions d'une société ; un droit d'usufruit sur une maison."},{"corrige":[{"p":"**Immeuble par nature** : le champ. **Immeuble par destination** : le tracteur, meuble affecté par le propriétaire à l'exploitation de son immeuble (*accessorium sequitur principale*). **Meuble par nature** : la voiture. **Meuble par détermination de la loi** : les actions. **Immeuble par l'objet** : l'usufruit d'une maison, droit qui porte sur un immeuble."}]}],"dc/extrapatrimoniaux":[{"h":"Exercice d'application"},{"p":"Un journal révèle la maladie d'une chanteuse et publie sa photo prise à son insu à l'hôpital. Quels droits sont atteints et sur quel fondement agir ?"},{"corrige":[{"p":"Sont atteints le **droit au respect de la vie privée** (l'état de santé) et le **droit à l'image** (photo publiée sans consentement), deux **droits de la personnalité**."},{"p":"Elle peut obtenir des **dommages-intérêts** sur le fondement de l'**article 1382 du Code civil** (faute, dommage, lien de causalité), et l'arrêt de la diffusion."}]}],"dc/nom":[{"h":"Exercice d'application"},{"p":"Aïcha, née hors mariage, a été reconnue d'abord par sa mère, Mme Koné, puis par son père, M. Bamba, qui veut qu'elle porte son seul nom. Quel nom portera-t-elle ?"},{"corrige":[{"p":"**Règle** : quand le père reconnaît l'enfant **en second**, l'enfant porte le **nom de la mère suivi du nom du père**, sans l'accord de la mère ; pour lui donner le **seul nom du père**, il faut le **consentement de la mère** (article 3, alinéa 3, de la loi sur le nom)."},{"p":"**Solution** : Aïcha portera « Koné Bamba », sauf si Mme Koné consent à ce qu'elle porte le seul nom « Bamba »."}]}],"dc/nom2":[{"h":"Exercice d'application"},{"p":"Un commerçant vend son fonds de commerce « Chez Diallo » avec son enseigne. M. Diallo peut-il ainsi vendre son nom ? Plus tard, un concurrent utilise le nom Diallo pour tromper la clientèle : que peut faire la famille ?"},{"corrige":[{"p":"Le nom est **inaliénable** : on ne le vend pas. Mais le **nom commercial** peut être cédé avec le fonds de commerce, pour sa seule exploitation : la cession de l'enseigne est valable."},{"p":"Le porteur du nom ou ses descendants peuvent **s'opposer à l'usurpation** du nom et demander des **dommages-intérêts** (protection du nom)."}]}],"dc/domicile":[{"h":"Exercice d'application"},{"p":"Kader, 15 ans, vit chez sa mère, qui a la garde depuis le divorce ; il passe ses vacances chez son père à Bouaké. Où est son domicile ? Où l'assigner s'il cause un dommage ?"},{"corrige":[{"p":"**Règle** : le mineur non émancipé a un **domicile légal** chez ses père et mère ; en cas de divorce, chez le parent qui a la **garde** (article 5)."},{"p":"**Solution** : le domicile de Kader est **chez sa mère** ; Bouaké n'est qu'une **habitation** occasionnelle. L'action se porte devant le tribunal du domicile du défendeur, et le mineur ne se défend qu'assisté de son représentant légal."}]}],"dc/etatcivil":[{"h":"Exercice d'application"},{"p":"Un enfant est né le 2 janvier 2026 à Yamoussoukro. Son père veut le déclarer le 15 avril 2026. Est-ce possible ?"},{"corrige":[{"p":"**Règle** : la naissance se déclare dans les **3 mois** de l'accouchement (article 41), devant l'officier de l'état civil du lieu de naissance."},{"p":"**Application** : le délai expire le 2 avril 2026 ; le 15 avril, il est dépassé."},{"p":"**Solution** : l'officier ne peut plus dresser l'acte. Il faut obtenir un **jugement supplétif d'acte de naissance**, transcrit ensuite sur les registres."}]}],"dc/etatcivil2":[{"h":"Exercice d'application"},{"p":"L'acte de naissance de Fatou porte « Fatoumata » au lieu de « Fatou », et indique par erreur le sexe masculin. Comment corriger ces erreurs ? Et si le registre a été entièrement détruit ?"},{"corrige":[{"p":"Ce sont des **erreurs matérielles** : elles relèvent de la **rectification administrative** (orthographe, sexe) ; les erreurs plus graves exigent une rectification judiciaire."},{"p":"Si **les deux exemplaires** du registre sont perdus, on procède à une **reconstitution** après enquête, ou l'on obtient un **jugement supplétif**."}]}],"dc/mineur":[{"h":"Exercice d'application"},{"p":"Sali, 15 ans, a acheté un cahier et un téléphone simple avec son argent de poche, puis a vendu seule le terrain que lui a légué sa grand-mère. Ces actes sont-ils valables ?"},{"corrige":[{"p":"Les achats du **cahier** et du **téléphone** sont des **actes de la vie courante** : le mineur peut les faire seul ; ils sont **valables**."},{"p":"La **vente du terrain** est un **acte de disposition** grave : même son représentant ne pourrait la faire qu'avec une autorisation. Faite par la mineure seule, elle est **nulle** (article 37). Le mineur ne restitue que ce qui a tourné à son profit."}]}],"dc/autorite":[{"h":"Exercice d'application"},{"p":"Les parents de Koffi, mariés, ne s'entendent pas sur l'école de leur fils. Le père inscrit seul l'enfant dans un établissement. L'école peut-elle accepter ? Qui tranche le conflit ?"},{"corrige":[{"p":"Les parents mariés exercent l'**autorité parentale en commun**. Envers les **tiers de bonne foi**, chaque parent qui accomplit seul un **acte usuel** est réputé agir avec l'accord de l'autre : l'école peut accepter l'inscription."},{"p":"En cas de conflit persistant, le **juge** tranche dans l'**intérêt de l'enfant**. Le choix de l'instruction fait partie de l'attribut d'**éducation**."}]}],"dc/controle":[{"h":"Exercice d'application"},{"p":"Une voisine recueille un enfant abandonné devant sa porte, sans prévenir personne. Que devait-elle faire ? Que risque-t-elle ?"},{"corrige":[{"p":"C'est une **délégation judiciaire** : la personne qui recueille un enfant sans l'intervention des parents doit en faire la **déclaration au juge des tutelles dans les 72 heures** (article 16). Si personne ne réclame l'enfant dans les **3 mois**, le juge peut lui confier une partie des droits."},{"p":"À défaut de déclaration, elle encourt **1 à 3 mois d'emprisonnement** et **100 000 à 500 000 F** d'amende."}]}],"dc/tutelle":[{"h":"Exercice d'application"},{"p":"Les deux parents de Yasmine, 10 ans, meurent dans un accident ; le dernier mourant avait désigné sa sœur comme tutrice par testament. Qui sera tuteur ? Ce tuteur peut-il vendre la maison de Yasmine ?"},{"corrige":[{"p":"La tutelle s'ouvre par le **décès des deux parents** (article 53). Le **tuteur testamentaire**, désigné par le dernier parent vivant, l'emporte (article 57) : la tante sera tutrice. À défaut, le conseil de famille aurait désigné un tuteur datif."},{"p":"La **vente d'un immeuble** du mineur exige l'**autorisation du conseil de famille** (ou du juge). La tutrice ne peut pas la faire seule ; elle ne peut jamais acheter elle-même les biens de la mineure."}]}],"dc/emancipation":[{"h":"Exercice d'application"},{"p":"Ali, 17 ans, est émancipé. Il veut louer un appartement, ouvrir une boutique et être adopté par son oncle. Le peut-il seul ?"},{"corrige":[{"p":"L'émancipé est **capable** d'accomplir tous les actes de la vie civile : il peut **louer** seul un appartement."},{"p":"Pour **faire le commerce**, il lui faut une **autorisation** inscrite au registre du commerce ; pour être **adopté**, le **consentement de ses parents** reste nécessaire (article 125)."}]}],"dc/pmclass":[{"h":"Exercice d'application"},{"p":"Des étudiants créent une association de révision et la déclarent à la préfecture ; d'autres créent une société pour vendre des fournitures et partager les bénéfices. Quelle est la nature de chaque groupement ?"},{"corrige":[{"p":"**L'association déclarée** est une **personne morale de droit privé à but non lucratif** (loi n° 60-315) : elle peut ouvrir un compte, louer un local, agir en justice."},{"p":"**La société** est une **personne morale de droit privé à but lucratif** ; elle acquiert la personnalité par l'**immatriculation au RCCM**. À la dissolution, ses biens sont partagés entre les associés, ce qui n'est pas le cas d'une association."}]}],"dc/pmregime":[{"h":"Exercice d'application"},{"p":"Une société a 50 millions FCFA de dettes et ne peut plus payer. Les créanciers peuvent-ils saisir la maison personnelle d'un associé ?"},{"corrige":[{"p":"La personne morale a un **patrimoine propre**, distinct de celui de ses membres : les dettes de la société sont d'abord **celles de la société**."},{"p":"En principe, les créanciers saisissent les biens de la société, non la maison de l'associé, sauf dans les formes de société où les associés répondent personnellement des dettes, ou en cas de garantie personnelle (caution)."}]}],"dm/charia":[{"h":"Exercice d'application"},{"p":"Un camarade affirme : « La Charia, ce sont seulement les peines corporelles. » Corrige-le en trois phrases."},{"corrige":[{"p":"Au sens linguistique, la Charia est le **chemin qui mène à la source d'eau** : la voie qui fait vivre. Au sens religieux, c'est ce qu'Allah a établi comme législation, couvrant la **croyance**, le **culte** et le **comportement**."},{"p":"Réduire la Charia aux sanctions pénales en donne une image **réductrice**. On distingue d'ailleurs la **Charia**, Loi révélée, et le **Fiqh**, effort humain de compréhension."}]}],"dm/coran":[{"h":"Exercice d'application"},{"p":"Distingue une sourate mecquoise d'une sourate médinoise par sa période et son contenu."},{"corrige":[{"p":"**Mecquoise** : révélée **avant l'Hégire** (610-622), elle porte surtout sur le dogme, la foi, l'unicité de Dieu (**Tawhîd**) et la morale."},{"p":"**Médinoise** : révélée **après l'Hégire** (622-632), dans une communauté organisée, elle contient davantage de **règles juridiques et sociales**."}]}],"dm/sunna":[{"h":"Exercice d'application"},{"p":"Un compagnon mange un plat devant le Prophète, qui le voit et ne dit rien. De quel élément de la Sunna s'agit-il ? Quelle est sa valeur ?"},{"corrige":[{"p":"C'est une **approbation tacite** (*Taqrîr*) : ce que le Prophète a vu faire sans le désapprouver."},{"p":"Elle fait partie de la **Sunna**, deuxième source du droit, au même titre que les **dits** (*qawl*) et les **actes** (*fi'l*), à condition que le hadith qui la rapporte soit authentique (vérification de l'**isnâd** et du **matn**)."}]}],"dm/idjma":[{"h":"Exercice d'application"},{"p":"Pourquoi l'Idjma' rend-il une règle définitive, et pourquoi la pratique religieuse en Côte d'Ivoire suit-elle surtout une école plutôt qu'une autre ?"},{"corrige":[{"p":"L'Idjma' est l'**accord unanime des savants compétents** d'une époque ; il se fonde sur le hadith « Ma communauté ne se réunira jamais sur une erreur » : la règle devient **définitive** et s'impose aux générations suivantes."},{"p":"L'école **malékite** (Mâlik ibn Anas) est dominante en **Afrique de l'Ouest** : c'est elle que l'on rencontre le plus souvent en Côte d'Ivoire."}]}],"dm/qiyas":[{"h":"Exercice d'application"},{"p":"Applique le Qiyas : le Coran interdit le vin ; que dire d'une boisson moderne enivrante ? Identifie l'asl, le far', la 'illa et le hukm."},{"corrige":[{"p":"**Asl** : le vin (*khamr*), cas réglé par le texte. **Far'** : la boisson moderne, cas nouveau sans texte. **'Illa** : l'**effet enivrant**, cause commune. **Hukm** : l'**interdiction**, étendue au cas nouveau."},{"p":"Le Qiyas ne crée pas une règle *ex nihilo* : il **étend** une règle déjà posée par un texte."}]}],"dm/complement":[{"h":"Exercice d'application"},{"p":"Une application stricte de l'analogie conduirait à une solution injuste. Quelle méthode permet au juriste de s'en écarter ? Et quelle source permet de prendre une règle utile à tous sans texte précis ?"},{"corrige":[{"p":"L'**Istihsân** (préférence juridique) permet de préférer une solution **plus équitable** que celle de l'analogie stricte ; il joue un rôle proche de l'**équité**."},{"p":"L'**Istislâh** (*maslaha mursala*) permet d'édicter des règles dans l'**intérêt général**, même sans texte, au service des objectifs de la Charia (vie, religion, raison, biens, filiation)."}]}],"dm/etat":[{"h":"Exercice d'application"},{"p":"Définis le Kanun, la Majalla et le Talfîq."},{"corrige":[{"p":"**Kanun** : loi séculière édictée par le sultan ottoman, à côté de la Charia. **Majalla** : premier grand **code civil** ottoman tiré du fiqh hanafite (1869-1876). **Talfîq** : technique qui **combine les avis de plusieurs écoles** pour rédiger un code."}]}],"dm/revelation":[{"h":"Exercice d'application"},{"p":"Compare les compilations du Coran sous Abû Bakr et sous 'Uthmân."},{"corrige":[{"table":{"h":["","Abû Bakr (1er calife)","'Uthmân (3e calife)"],"r":[["Cause","Mort de nombreux mémorisateurs à Yamâma","Divergences de lecture entre les régions"],["But","Rassembler et sauver le texte","Uniformiser et diffuser un texte unique"],["Résultat","Les *suhuf* (feuillets)","La vulgate othmanienne (*Mushaf 'uthmânî*), copies envoyées dans les grandes villes"]]}}]}],"dm/synthese":[{"h":"Exercice d'application"},{"p":"Classe dans l'ordre ces sources du droit musulman, du rang le plus élevé au plus bas : Qiyas, Coran, Idjma', Sunna, 'Urf."},{"corrige":[{"p":"1. **Coran** ; 2. **Sunna** (sources révélées) ; 3. **Idjma'** ; 4. **Qiyas** (sources dérivées) ; puis les sources **complémentaires**, dont la coutume (**'Urf**), avec l'Istihsân et l'Istislâh."}]}],"oj/introduction":[{"h":"Exercice d'application"},{"p":"Cite les six caractères de l'organisation judiciaire et explique la « spécialisation » par un exemple."},{"corrige":[{"p":"**Légalité, hiérarchie, spécialisation, unicité, indépendance, permanence** (« Le Haut Sénat Unit l'Indépendance Permanente »)."},{"p":"La **spécialisation** répartit les affaires par matière : un litige entre commerçants va au **tribunal de commerce**, un licenciement au **tribunal du travail**, un délit commis par un mineur au **tribunal pour enfants**."}]}],"oj/separation":[{"h":"Exercice d'application"},{"p":"Le ministre de la Justice ordonne à un juge du siège de condamner un opposant. Un plaideur se plaint de devoir payer son avocat alors que « la justice est gratuite ». Que répondre ?"},{"corrige":[{"p":"**Au ministre** : la **séparation des pouvoirs** interdit à l'exécutif de juger ou de dicter une décision ; le juge du siège ne reçoit d'ordre de personne."},{"p":"**Au plaideur** : la **gratuité** signifie seulement qu'**on ne paie pas son juge**. Les **dépens** et les **honoraires d'avocat** restent dus ; les plus démunis peuvent demander l'**assistance judiciaire**."}]}],"oj/egalite":[{"h":"Exercice d'application"},{"p":"Pourquoi un mineur délinquant n'est-il pas jugé par le même tribunal qu'un adulte, sans violer le principe d'égalité ? Et pourquoi la Cour de cassation n'est-elle pas un troisième degré ?"},{"corrige":[{"p":"L'égalité admet des différences fondées sur une **situation objective** : la protection du mineur justifie le **tribunal pour enfants**."},{"p":"La Cour de cassation juge **le droit, non les faits** : elle vérifie l'application de la loi. Le double degré s'arrête à la **cour d'appel**."}]}],"oj/contradictoire":[{"h":"Exercice d'application"},{"p":"Le juge fonde sa décision sur un document que l'une des parties n'a jamais pu consulter. Un autre juge est le cousin germain du défendeur. Quels principes sont violés et quels remèdes existent ?"},{"corrige":[{"p":"**Le document** : violation du **contradictoire** ; chaque partie doit connaître et pouvoir discuter les pièces de l'autre. La décision peut être annulée par la voie de recours."},{"p":"**Le cousin** : atteinte à l'**impartialité**. Le juge doit se **déporter** ; à défaut, la partie peut demander sa **récusation** pour parenté."}]}],"oj/tpi":[{"h":"Exercice d'application"},{"p":"Une affaire de divorce, un délit de vol et un litige commercial dans une ville sans tribunal de commerce : quelle juridiction est compétente ?"},{"corrige":[{"p":"Le **tribunal de première instance**, juridiction de **droit commun** du premier degré, est compétent pour les trois : le divorce (matière civile), le vol (délit, chambre correctionnelle) et le litige commercial (chambre commerciale, faute de tribunal de commerce)."}]}],"oj/exception1":[{"h":"Exercice d'application"},{"p":"Deux commerçants se disputent une facture de 10 millions FCFA. Un salarié conteste son licenciement. Quelle juridiction saisir, et que faut-il faire avant ?"},{"corrige":[{"p":"**La facture** : le **tribunal de commerce**, après une **tentative de règlement amiable obligatoire**, sous peine d'irrecevabilité. À 10 millions FCFA (moins de 25 millions), il statue en **premier et dernier ressort** : pas d'appel, seulement un pourvoi."},{"p":"**Le licenciement** : le **tribunal du travail**, après une **tentative de conciliation devant l'inspecteur du travail**."}]}],"oj/exception2":[{"h":"Exercice d'application"},{"p":"Un garçon de 16 ans commet un vol ; un adulte commet un meurtre ; un directeur détourne plusieurs milliards de deniers publics. Qui juge chacun ?"},{"corrige":[{"p":"Le **mineur** : le **tribunal pour enfants** (huis clos, priorité aux mesures éducatives). Le **meurtre** commis par un majeur : le **tribunal criminel**, après instruction obligatoire. Le **détournement** massif de deniers publics : le **Pôle pénal économique et financier (PPEF)**."}]}],"oj/appel":[{"h":"Exercice d'application"},{"p":"Le tribunal de commerce d'Abidjan a rendu un jugement en premier ressort ; le tribunal de première instance de Daloa aussi. Devant quelle juridiction faire appel dans chaque cas ?"},{"corrige":[{"p":"Contre le jugement du **tribunal de commerce** : la **cour d'appel de commerce**, qui siège à Abidjan et statue dans un délai de deux mois."},{"p":"Contre le jugement du **TPI de Daloa** : la **cour d'appel** dans le ressort de laquelle il se trouve (Daloa). L'appel a un **effet suspensif**, sauf exécution provisoire."}]}],"oj/cc-comptes":[{"h":"Exercice d'application"},{"p":"Un candidat conteste les résultats de l'élection présidentielle. Un comptable public est soupçonné d'avoir mal tenu ses comptes. Quelle juridiction est compétente ?"},{"corrige":[{"p":"**L'élection présidentielle** : le **Conseil constitutionnel**, juge du contentieux de cette élection ; ses décisions ne sont susceptibles d'**aucun recours**."},{"p":"**Les comptes** : la **Cour des comptes**, institution supérieure de contrôle des finances publiques, qui juge les comptes des comptables publics."}]}],"oj/cassation":[{"h":"Exercice d'application"},{"p":"La cour d'appel a condamné Awa sans expliquer pourquoi. Un arrêté du ministre lèse un fonctionnaire. Quel recours et devant qui ?"},{"corrige":[{"p":"**Pour Awa** : un **pourvoi en cassation** devant la **Cour de cassation**, pour **défaut de motifs**."},{"p":"**Pour le fonctionnaire** : un **recours pour excès de pouvoir** devant le **Conseil d'État**, juge suprême de l'ordre administratif. Si les deux ordres se déclarent incompétents, le **Tribunal des conflits** tranche (conflit négatif)."}]}],"oj/nonpermanentes":[{"h":"Exercice d'application"},{"p":"Un soldat déserte son poste. Un ministre en fonction est accusé de corruption commise dans l'exercice de ses fonctions. Qui juge ?"},{"corrige":[{"p":"**Le soldat** : le **tribunal militaire** (infraction militaire)."},{"p":"**Le ministre** : la **Haute Cour de justice**, compétente pour les crimes et délits commis par les membres du Gouvernement **dans l'exercice de leurs fonctions** ; elle est saisie par une résolution de mise en accusation du Parlement."}]}],"oj/communautaires":[{"h":"Exercice d'application"},{"p":"Une société ivoirienne perd en appel un litige fondé sur un Acte uniforme OHADA. Devant quelle juridiction se pourvoir ? Où siège-t-elle ?"},{"corrige":[{"p":"Devant la **Cour commune de justice et d'arbitrage (CCJA)** de l'OHADA, qui statue en cassation sur les décisions d'appel rendues en application des **Actes uniformes** ; elle siège à **Abidjan**. Si elle casse, elle **évoque** et statue sur le fond."}]}],"oj/magistrats":[{"h":"Exercice d'application"},{"p":"À l'audience, qui est assis et qui se lève ? Qui peut recevoir des instructions du ministre de la Justice ?"},{"corrige":[{"p":"Les **magistrats du siège** jugent : c'est la **magistrature assise** ; ils sont indépendants et inamovibles."},{"p":"Les **magistrats du parquet** se lèvent pour requérir : c'est la **magistrature debout**. Hiérarchisés, ils peuvent recevoir des instructions écrites, mais « la plume est serve, la parole est libre »."}]}],"oj/recrutement":[{"h":"Exercice d'application"},{"p":"Comment devient-on magistrat en Côte d'Ivoire ? Décris les étapes."},{"corrige":[{"p":"1. **Concours** d'accès à la magistrature, ouvert aux diplômés en droit (voie principale ; le recrutement direct sur titre est exceptionnel). 2. Formation à l'**INFJ** comme **auditeur de justice** : formation théorique puis stages. 3. **Affectation** selon le classement, les besoins et l'avis du **Conseil supérieur de la magistrature**, puis prestation de serment."}]}],"oj/statut":[{"h":"Exercice d'application"},{"p":"Un juge veut être élu conseiller municipal tout en restant magistrat ; un autre veut juger une affaire où son frère est partie. Le peuvent-ils ?"},{"corrige":[{"p":"**Non** pour le premier : la fonction de magistrat est **incompatible** avec tout **mandat électif**."},{"p":"**Non** pour le second : un magistrat ne peut juger une affaire concernant un **proche** (le frère est parent au **2e degré** en ligne collatérale)."}]}],"oj/responsabilite":[{"h":"Exercice d'application"},{"p":"Un justiciable estime qu'un juge a commis une faute de service qui lui a causé un préjudice. Peut-il poursuivre le juge personnellement ?"},{"corrige":[{"p":"Non : pour ses fautes de service, le magistrat n'est pas poursuivi personnellement par le justiciable ; c'est l'**État** qui répond du fonctionnement défectueux de la justice."},{"p":"Le magistrat reste exposé à une **sanction disciplinaire** et, s'il commet une infraction (corruption, déni de justice), à une **responsabilité pénale** selon des règles de privilège de juridiction."}]}],"oj/avocats":[{"h":"Exercice d'application"},{"p":"Un avocat laisse passer le délai d'appel de son client. Un autre veut ouvrir une boutique de téléphones. Que risquent-ils ?"},{"corrige":[{"p":"**Le délai manqué** engage la **responsabilité civile** de l'avocat envers son client ; d'où son **assurance obligatoire**."},{"p":"**La boutique** : la profession d'avocat est **incompatible** avec toute **activité commerciale** ; il s'expose à des sanctions disciplinaires."}]}],"oj/notaire":[{"h":"Exercice d'application"},{"p":"Quels actes un étudiant devra-t-il passer devant notaire dans sa vie ? Donne trois exemples et dis ce que leur apporte le notaire."},{"corrige":[{"p":"Une **vente immobilière**, un **contrat de mariage**, une **donation** ou un **testament**, les **statuts** d'une société, un **prêt hypothécaire**."},{"p":"Le notaire leur donne l'**authenticité** : l'acte fait foi jusqu'à **inscription de faux** et peut avoir **force exécutoire**. Il conserve l'original et doit **conseiller** les parties."}]}],"oj/commissaire":[{"h":"Exercice d'application"},{"p":"Un bailleur veut faire constater l'état d'un appartement, puis faire exécuter un jugement d'expulsion. À qui s'adresser ?"},{"corrige":[{"p":"Au **commissaire de justice** (loi n° 2018-974), qui réunit les anciens huissiers et commissaires-priseurs : il dresse le **constat** (mission extrajudiciaire) et **exécute** le jugement (mission judiciaire), après l'avoir signifié."}]}],"oj/greffier":[{"h":"Exercice d'application"},{"p":"Après le jugement, Koffi veut faire saisir les biens de son débiteur. Quel document doit-il obtenir, auprès de qui ?"},{"corrige":[{"p":"Il doit obtenir la **grosse** du jugement, copie revêtue de la **formule exécutoire**, délivrée par le **greffier**. L'original, la **minute**, reste conservé au greffe."}]}],"info/composants":[{"h":"Exercice d'application"},{"p":"Classe ces éléments : le clavier, l'écran, la clé USB, le processeur, la RAM, Windows."},{"corrige":[{"p":"**Périphérique d'entrée** : le clavier. **De sortie** : l'écran. **D'entrée-sortie** : la clé USB. **Composants internes** : le processeur (exécute les instructions) et la RAM (mémoire vive, volatile). **Logiciel** : Windows, système d'exploitation qui gère le matériel."}]}]};
  for (const k in X) { const L = les(k); if (L) L.body.push(...X[k]); }
  // TEE : chaque phrase du fascicule, puis sa correction à déplier
  for (const id of ["n1-exos","n2-exos"]) { const L = les("tee/" + id); const t = L && L.body.find(b => b.table); if (!t) continue;
    L.body.splice(L.body.indexOf(t), 1, ...t.table.r.flatMap((r, n) => [{ p: "**" + (n + 1) + ".** " + r[0] }, { corrige: [{ p: r[1] }] }]));
    L.body[0] = { p: L.body[0].p.replace("puis vérifie avec la colonne de droite", "puis ouvre la correction") }; }
})();
