M_METHO.quiz.push(...[{"q":"L'introduction d'une dissertation juridique compte…","a":["six éléments : accroche, définitions, délimitation, intérêt, problématique, annonce du plan","trois éléments","deux parties","une seule phrase"],"c":0,"e":"Ils s'enchaînent dans cet ordre."},{"q":"Dans une dissertation juridique, la conclusion est…","a":["facultative","obligatoire et longue","un résumé des deux parties","interdite"],"c":0,"e":"Elle est courte et ouvre le sujet."},{"q":"Qualifier les faits, c'est…","a":["les nommer en termes juridiques","les résumer","donner son avis","les recopier"],"c":0,"e":"On rattache les faits à une catégorie juridique."},{"q":"« En l'espèce » annonce…","a":["l'application de la règle aux faits","la règle de droit","la solution","la problématique"],"c":0,"e":"« En droit » annonce la règle."},{"q":"Dans un cas pratique, on classe les problèmes…","a":["du préalable vers la conséquence","du plus facile au plus difficile","par ordre alphabétique","au hasard"],"c":0,"e":"On règle d'abord la question dont dépendent les autres."},{"q":"Deux difficultés qui se résolvent par la même règle…","a":["peuvent être réunies en un seul problème","doivent toujours être séparées","ne sont pas traitées","font l'objet d'une conclusion"],"c":0,"e":"On évite de répéter la même règle."},{"q":"Dans la rubrique « Faits » de la fiche, on écrit…","a":["les faits matériels avec ses propres mots, sans les « que »","les prétentions des parties","les « attendu que » recopiés","la solution"],"c":0,"e":"Les prétentions relèvent de la procédure."},{"q":"Dans la fiche, la solution s'écrit…","a":["le motif d'abord, le dispositif ensuite","le dispositif d'abord","sans motif","en latin"],"c":0,"e":"« Au motif que…, la Cour casse et annule… »."},{"q":"Dans un arrêt de cassation, le visa est…","a":["le texte de loi sur lequel la Cour fonde sa décision","la signature du greffier","le résumé des faits","le dispositif"],"c":0,"e":"« Vu l'article… »."},{"q":"La problématique doit être…","a":["une question juridique qui oriente tout le devoir","une simple répétition du sujet","une citation","placée en conclusion"],"c":0,"e":"Le plan y répond."},{"q":"Peut-on ajouter dans un cas pratique un fait que l'énoncé ne contient pas ?","a":["Non, on raisonne sur les faits donnés","Oui, toujours","Oui, si cela simplifie","Seulement en conclusion"],"c":0,"e":"Ce qui n'est pas dit ne doit pas être inventé."},{"q":"Un « chapeau » dans une dissertation est…","a":["un court paragraphe qui annonce les sous-parties","la conclusion","le titre du sujet","la bibliographie"],"c":0,"e":"Il se place sous le titre de chaque partie."},{"q":"Le problème de droit de la fiche se pose…","a":["en termes abstraits, sans le nom des parties","avec le nom des parties","à la première juridiction","en citant l'arrêt"],"c":0,"e":"Il s'adresse à la dernière juridiction saisie."},{"q":"La transition entre les deux parties sert à…","a":["faire le lien entre la partie I et la partie II","conclure le devoir","répéter la problématique","annoncer la bibliographie"],"c":0,"e":"Elle assure l'enchaînement du raisonnement."},{"q":"« Par ces motifs » ouvre…","a":["le dispositif de l'arrêt","le visa","les faits","les moyens du pourvoi"],"c":0,"e":"Après « Par ces motifs » vient la décision."}]);
