// ===== Notes du 11 novembre 2026 : présomption d'innocence, « l'exception confirme la règle », pas de plan dialectique
(function () {
  const get = (S, id) => S.lessons.find(l => l.id === id);
  const interp = get(M_INTRO, "interpretation");
  const ad = interp && interp.body.find(b => b.table && b.table.h[0] === "Adage");
  if (ad) ad.table.r.push(
    ["*Exceptio firmat regulam in casibus non exceptis*", "L'exception confirme la règle **pour les cas non exceptés** : en prévoyant expressément une exception, le législateur montre que la règle s'applique à tous les autres cas"]
  );
  const preuve = get(M_INTRO, "chargepreuve");
  if (preuve) { const i = preuve.body.findIndex(b => b.h === "Exercice d'application");
    preuve.body.splice(i < 0 ? preuve.body.length : i, 0,
      { h: "§ 3. En matière pénale : la présomption d'innocence" },
      { p: "Toute personne poursuivie est **présumée innocente jusqu'à ce que sa culpabilité soit légalement établie** par un jugement. C'est donc à l'accusation (le ministère public) de prouver l'infraction ; le doute profite à l'accusé. Ce principe figure dans la Déclaration universelle des droits de l'homme (article 11), dans la Déclaration de 1789 (article 9) et dans la Constitution ivoirienne." },
      { box: "La présomption d'innocence est une présomption **simple** : elle tombe devant la preuve de la culpabilité, apportée dans un procès équitable où la défense a pu s'exprimer.", title: "Lien avec le § 2", kind: "cle" }); }
  const diss = get(M_METHO, "methode");
  if (diss) { const i = diss.body.findIndex(b => b.h === "La conclusion");
    diss.body.splice(i < 0 ? diss.body.length : i, 0,
      { box: "La dissertation juridique ne suit **pas** le plan dialectique « thèse, antithèse, synthèse » des dissertations de philosophie. On ne défend pas une thèse pour la réfuter ensuite : on construit une **démonstration en deux parties**, chacune appuyée sur des règles, des décisions et des arguments juridiques.", title: "Pas de plan dialectique", kind: "piege" }); }
  M_INTRO.quiz.push({ q: "« L'exception confirme la règle » signifie que…", a: ["la règle s'applique à tous les cas que l'exception n'a pas prévus", "une exception annule la règle", "toute règle a nécessairement une exception", "le juge peut créer des exceptions"], c: 0, e: "*Exceptio firmat regulam in casibus non exceptis*." },
    { q: "En matière pénale, qui doit prouver la culpabilité ?", a: ["l'accusation (le ministère public)", "l'accusé", "le greffier", "le témoin"], c: 0, e: "Toute personne poursuivie est présumée innocente." });
  M_INTRO.cards.push(["Présomption d'innocence", "Toute personne poursuivie est présumée innocente jusqu'à ce que sa culpabilité soit établie"],
    ["L'exception confirme la règle", "La règle vaut pour tous les cas non exceptés"]);
  M_CONST.quiz.push({ q: "Le droit constitutionnel est une branche…", a: ["du droit public", "du droit privé", "du droit international privé", "du droit commercial"], c: 0, e: "Il organise l'État et le pouvoir politique." },
    { q: "Les deux objets du droit constitutionnel sont…", a: ["les institutions et les droits et libertés", "les contrats et la responsabilité", "les impôts et le budget", "les crimes et les peines"], c: 0, e: "Il organise le pouvoir pour mieux le limiter." },
    { q: "Au sens formel, le droit constitutionnel comprend…", a: ["les règles inscrites dans le texte de la Constitution", "toutes les règles sur le pouvoir, quelle que soit leur source", "la jurisprudence administrative", "les coutumes locales"], c: 0, e: "Le sens matériel retient toutes les règles qui organisent le pouvoir." });
  M_CONST.cards.unshift(["Droit constitutionnel", "Droit public de l'organisation de l'État, du pouvoir politique et des libertés"], ["Sens formel / matériel", "Texte de la Constitution / toutes les règles qui organisent le pouvoir"]);
  M_METHO.quiz.push({ q: "La dissertation juridique suit…", a: ["une démonstration en deux parties, sans plan dialectique", "le plan thèse, antithèse, synthèse", "un plan en trois parties obligatoires", "un plan chronologique libre"], c: 0, e: "Le plan dialectique est propre à la dissertation de philosophie." });
})();

// ===== Méthodologie : corrections du professeur sur la fiche méthode (12 novembre 2026)
// cas pratique : une introduction et un développement ; plan I/A/B peu adapté ; pas d'intitulés dans la copie ; fiche de décision : nature, faits, procédure, problème, solution
(function () {
  const get = id => M_METHO.lessons.find(l => l.id === id);
  const cp = get("caspratique");
  if (cp) { const B = cp.body;
    const i = B.findIndex(b => b.h === "La structure du devoir : plusieurs problèmes");
    if (i >= 0) B.splice(i + 1, 0,
      { p: "Lorsque les faits soulèvent plusieurs problèmes, le devoir comprend **une introduction** et **un développement**." },
      { h: "L'introduction" });
    const j = B.findIndex(b => b.p && /^Puis chaque problème est traité/.test(b.p));
    if (j >= 0) B.splice(j, 1, { h: "Le développement" }, { p: "Dans le développement, **chaque problème** est traité sous un titre numéroté (**I**, **II**, **III**…), en six temps :" });
    const k = B.findIndex(b => b.box && /n'est \*\*pas autorisé\*\*/.test(b.box));
    if (k >= 0) B[k] = { box: "Le plan en deux parties et deux sous-parties (I, A, B ; II, A, B) est celui de la dissertation et du commentaire. Il est **peu adapté** au cas pratique : on numérote les problèmes (I, II, III…), sans nécessairement de subdivisions.", title: "Le plan I / A / B est peu adapté", kind: "piege" };
    const r = B.findIndex(b => b.h === "Les règles de rédaction");
    if (r >= 0) B.splice(r, 0, { box: "Les mots « résumé des faits », « qualification », « problèmes », « plan » servent à construire le devoir au brouillon. **Dans la copie, on ne les écrit pas comme intitulés** : les étapes s'enchaînent en paragraphes liés par des transitions. Seuls les problèmes du développement reçoivent un titre numéroté (I, II…).", title: "Pas d'intitulés dans la rédaction", kind: "cle" }); }
  const LAB = /^\*\*(Résumé des faits|Qualification juridique|Qualification|Problèmes de droit|Problèmes|Problème de droit|Plan)\.\*\* /;
  const strip = bs => bs.forEach(b => { if (b.quote && LAB.test(b.quote)) b.quote = b.quote.replace(LAB, ""); if (b.corrige) strip(b.corrige); });
  for (const id of ["caspratique", "casexemple", "casexo", "atelier3"]) { const L = get(id); if (L) strip(L.body); }
  const ex = get("casexemple");
  if (ex) {
    if (ex.body[0] && ex.body[0].p) ex.body[0].p += " Comme dans une vraie copie, les étapes s'enchaînent sans intitulés : chaque paragraphe joue son rôle (faits, qualification, problèmes, annonce du plan, puis chaque problème)."; }
  const fd = get("fichedecision");
  if (fd) { const B = fd.body;
    if (B[0] && B[0].p) B[0] = { p: "La **fiche de décision** est le résumé ordonné d'une décision de justice. Elle se dresse en **cinq étapes** : la **nature** de la décision, les **faits**, la **procédure**, le **problème de droit** et la **solution**. Savoir la faire, c'est savoir lire une décision ; elle est aussi le squelette du commentaire." };
    B.forEach(b => { if (b.table) b.table.r.forEach(r => { if (r[0] === "**1. Les références**") r[0] = "**1. La nature de la décision** (les références)"; if (r[0] === "**Références**") r[0] = "**Nature de la décision** (références)"; }); }); }
  for (const id of ["fichedecision", "ficheexo", "atelier4"]) { const L = get(id); if (!L) continue;
    const fix = bs => bs.forEach(b => { if (b.quote) b.quote = b.quote.replace(/^\*\*Références\.\*\* /, "**Nature de la décision.** "); if (b.corrige) fix(b.corrige); });
    fix(L.body); }
})();
